INSERT INTO _n1_b9_guard_0124(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2027-01-21' AND '2027-02-03' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3561','2027-01-21','補償','ほしょう','보상; 손실을 메움','損害・損失・不利益などを金銭その他で埋め合わせること。','工事の遅延によって生じた損害をどこまで補償するか、契約内容を確認した。','공사 지연으로 생긴 손해를 어디까지 보상할지 계약 내용을 확인했다.'),
('n1-3562','2027-01-21','代用','だいよう','대용; 대신 사용함','本来使うものの代わりに、別のものを用いること。','専用部品が届くまで、同じ性能を持つ別の部品で代用することにした。','전용 부품이 도착할 때까지 같은 성능의 다른 부품으로 대용하기로 했다.'),
('n1-3563','2027-01-21','原作','げんさく','원작; 각색·번역 전의 본래 작품','映画・ドラマ・漫画・翻訳などのもとになった、元の作品。','映画版では結末が原作と大きく異なっている。','영화판에서는 결말이 원작과 크게 다르다.'),
('n1-3564','2027-01-21','一括','いっかつ','일괄; 한꺼번에 묶어 처리함','複数のもの・処理・支払いなどを一つにまとめて、一度に扱うこと。','複数の請求書を一括して処理できるよう、経理システムを改修した。','여러 청구서를 일괄 처리할 수 있도록 회계 시스템을 수정했다.'),
('n1-3565','2027-01-21','悪口','あっこう','악담; 욕설; 험담','人を悪く言うこと。特に、相手をののしったり中傷したりする言葉。','匿名だからといって、他人への悪口や中傷が許されるわけではない。','익명이라고 해서 타인에 대한 악담이나 비방이 허용되는 것은 아니다.'),
('n1-3566','2027-01-21','点検','てんけん','점검; 하나하나 확인함','設備・機械・状態などに異常や問題がないか、一つずつ調べて確認すること。','事故を防ぐため、作業開始前に機器の安全点検を必ず行う。','사고를 막기 위해 작업 시작 전에 기기의 안전 점검을 반드시 실시한다.'),
('n1-3567','2027-01-21','得点','とくてん','득점; 얻은 점수','競技・試験などで点を得ること。また、得た点数。','後半に連続して得点し、チームは逆転勝利を収めた。','후반에 연속 득점해 팀은 역전승을 거두었다.'),
('n1-3568','2027-01-21','慣らす','ならす','익숙하게 하다; 적응시키다; 길들이다','人・動物・物などをある環境・使用状態に慣れさせる。','新しい靴は少しずつ履いて足に慣らしたほうがいい。','새 신발은 조금씩 신어 발에 익숙하게 하는 것이 좋다.'),
('n1-3569','2027-01-21','定める','さだめる','정하다; 규정하다','規則・方針・期限・基準などを決める。','社内規程では、重要データの保存期間を五年間と定めている。','사내 규정에서는 중요 데이터의 보존 기간을 5년으로 정하고 있다.'),
('n1-3570','2027-01-21','催す','もよおす','개최하다; 치르다; 느끼다','会・行事などを開く。また、眠気・吐き気などの感覚が起こる。','地域交流を目的とした催しを毎年秋に催している。','지역 교류를 목적으로 한 행사를 매년 가을 개최하고 있다.'),
('n1-3571','2027-01-21','構える','かまえる','자세를 취하다; 마련하다; 차리다','武器・体などをある姿勢に整える。また、店・家・拠点などを設ける。','会社は駅の近くに新しい事務所を構えた。','회사는 역 근처에 새 사무실을 마련했다.'),
('n1-3572','2027-01-21','導く','みちびく','이끌다; 인도하다','目的地・結論・状態などに向かうよう人や物事を案内し、方向づける。','複数の証拠を組み合わせることで一つの結論を導いた。','여러 증거를 조합해 하나의 결론을 이끌어냈다.'),
('n1-3573','2027-01-21','歩む','あゆむ','걷다; 길을 나아가다; 과정을 밟다','歩いて進む。また比喩的に、人生・歴史・進路などを進んでいく。','彼は研究者として独自の道を歩んできた。','그는 연구자로서 독자적인 길을 걸어왔다.'),
('n1-3574','2027-01-21','栄える','さかえる','번영하다; 번성하다','国・都市・産業・家系などが発展し、勢いが盛んになる。','港の整備をきっかけに、この町は商業都市として栄えた。','항구 정비를 계기로 이 도시는 상업 도시로 번영했다.'),
('n1-3575','2027-01-21','逃す','のがす','놓치다; 기회를 잃다; 달아나게 하다','捕らえられた人・動物などを逃がす。また、機会・好機などをつかめず失う。','重要な変化の兆候を見逃さず、改善の機会を逃さないことが大切だ。','중요한 변화의 징후를 놓치지 않고 개선의 기회를 잃지 않는 것이 중요하다.'),
('n1-3576','2027-01-21','取り除く','とりのぞく','제거하다; 없애다','不要・有害・邪魔な物を、その場所や対象から取り去る。','データから重複した行を取り除いてから集計を行った。','데이터에서 중복된 행을 제거한 뒤 집계를 실시했다.'),
('n1-3577','2027-01-21','定まる','さだまる','정해지다; 확정되다','方針・位置・基準・予定などがはっきり決まり、変わらない状態になる。','仕様が定まらないまま開発を始めると、後で大きな手戻りが発生する。','사양이 확정되지 않은 채 개발을 시작하면 나중에 큰 재작업이 발생한다.'),
('n1-3578','2027-01-21','逃げ出す','にげだす','도망치다; 달아나다','危険・責任・嫌な状況などから急いで逃げ始め、その場を離れる。','大きな音に驚いた犬が庭から逃げ出してしまった。','큰 소리에 놀란 개가 마당에서 도망쳐 버렸다.'),
('n1-3579','2027-01-21','著書','ちょしょ','저서; 자신이 쓴 책','その人が書き著した書物。','彼の著書は専門的な内容を一般向けに分かりやすく解説している。','그의 저서는 전문적인 내용을 일반 독자에게 알기 쉽게 설명하고 있다.'),
('n1-3580','2027-01-21','複合','ふくごう','복합; 둘 이상이 합쳐짐','二つ以上の異なる要素が組み合わさって一つのものになること。また、組み合わせること。','原因は一つではなく、複数の要因が重なった複合的な問題だと考えられている。','원인은 하나가 아니라 여러 요인이 겹친 복합적인 문제라고 여겨지고 있다.'),
('n1-3581','2027-01-22','購読','こうどく','구독; 돈을 내고 계속 받아 읽음','新聞・雑誌・刊行物などを代金を払って継続的に読んだり受け取ったりすること。','紙の新聞をやめ、電子版だけを購読する読者が増えている。','종이 신문을 끊고 전자판만 구독하는 독자가 늘고 있다.'),
('n1-3582','2027-01-22','敗戦','はいせん','패전; 전쟁·전투에서 패함','戦争・戦闘に負けること。また、その敗北。','敗戦後の社会がどのように再建されたのかを資料から検証する。','패전 후 사회가 어떻게 재건되었는지를 자료를 통해 검증한다.'),
('n1-3583','2027-01-22','本体','ほんたい','본체; 중심이 되는 주요 부분','機械・装置・物などの中心となる主要部分。また、付属物を除いたものそのもの。','故障の原因がケーブルではなく、端末本体にあることが分かった。','고장 원인이 케이블이 아니라 단말기 본체에 있다는 것이 밝혀졌다.'),
('n1-3584','2027-01-22','河川','かせん','하천; 크고 작은 강','地表を流れる大小の川をまとめていう語。','大雨に備え、自治体は河川の水位を常時監視している。','폭우에 대비해 지자체는 하천 수위를 상시 감시하고 있다.'),
('n1-3585','2027-01-22','訂正','ていせい','정정; 잘못된 내용을 바로잡음','文章・発言・数字などの誤りを正しい内容に直すこと。','資料の数値に誤りがあったため、訂正版を全員に再送した。','자료의 수치에 오류가 있어 정정본을 전원에게 다시 보냈다.'),
('n1-3586','2027-01-22','究極','きゅうきょく','궁극; 끝까지 이른 최종·최고의 상태','物事を突き詰めていった最後の到達点。これ以上ない最終・最高の状態。','顧客の要望をすべて満たすことが、必ずしも究極の解決策とは限らない。','고객의 요구를 모두 충족하는 것이 반드시 궁극적인 해결책인 것은 아니다.'),
('n1-3587','2027-01-22','山脈','さんみゃく','산맥','山々が長く連なって一つの帯のようになっている地形。','この山脈が季節風を遮るため、東西で降水量に大きな差が生じる。','이 산맥이 계절풍을 막기 때문에 동서의 강수량에 큰 차이가 생긴다.'),
('n1-3588','2027-01-22','孤立','こりつ','고립; 고립됨','周囲とのつながりや支援を失い、単独の状態になること。','部署間の連携が弱いと、担当者が問題を一人で抱えて孤立しやすい。','부서 간 연계가 약하면 담당자가 문제를 혼자 떠안아 고립되기 쉽다.'),
('n1-3589','2027-01-22','契機','けいき','계기; 전환점이 되는 기회','物事が始まったり変化したりするきっかけ。','一度の障害対応を契機に、運用手順全体を見直すことになった。','한 번의 장애 대응을 계기로 운영 절차 전체를 재검토하게 되었다.'),
('n1-3590','2027-01-22','復旧','ふっきゅう','복구; 정상화','故障・災害などで損なわれたものを元の状態に戻すこと。','停電した設備は深夜までに復旧し、翌朝から通常運転に戻った。','정전된 설비는 심야까지 복구되어 다음 날 아침부터 정상 운전으로 돌아왔다.'),
('n1-3591','2027-01-22','協調','きょうちょう','협조; 조화롭게 협력함','互いに立場を調整し、力を合わせて調和を保つこと。','複数部署が協調して対応しなければ、全社的な障害は短時間で解決できない。','여러 부서가 협조해 대응하지 않으면 전사 장애를 단시간에 해결할 수 없다.'),
('n1-3592','2027-01-22','一帯','いったい','일대; 주변 지역 전체','ある場所を中心として、その周囲に広がる地域全体。','大雨の影響で駅周辺一帯が冠水し、交通が一時まひした。','폭우의 영향으로 역 주변 일대가 침수돼 교통이 한때 마비되었다.'),
('n1-3593','2027-01-22','用品','ようひん','용품; 특정 목적에 쓰는 물품','特定の目的・用途のために使う道具や物品。','災害用品は一か所にまとめ、家族全員が場所を把握しておくとよい。','재난 용품은 한곳에 모아 두고 가족 모두가 위치를 알아두는 것이 좋다.'),
('n1-3594','2027-01-22','内臓','ないぞう','내장; 몸속 장기','胸部・腹部など体内にある器官の総称。','健康診断では血液検査だけでなく、内臓の状態も詳しく調べる。','건강검진에서는 혈액검사뿐 아니라 내장의 상태도 자세히 조사한다.'),
('n1-3595','2027-01-22','反射','はんしゃ','반사; 반사 작용','光・音などが物体に当たって跳ね返ること。また、刺激に対し身体が無意識に反応すること。','強い光が窓ガラスに反射して、画面が一時的に見えにくくなった。','강한 빛이 유리창에 반사되어 화면이 한때 보기 어려워졌다.'),
('n1-3596','2027-01-22','潜入','せんにゅう','잠입; 몰래 들어감','人に知られないよう、ある場所・組織などへひそかに入り込むこと。','記者は実態を調べるため、関係者として現場に潜入した。','기자는 실태를 조사하기 위해 관계자로 가장해 현장에 잠입했다.'),
('n1-3597','2027-01-22','出動','しゅつどう','출동','特定の任務・目的のために、人員や部隊などが現場へ向かうこと。','通報を受けて消防隊が直ちに出動し、周辺住民を避難させた。','신고를 받고 소방대가 즉시 출동해 주변 주민을 대피시켰다.'),
('n1-3598','2027-01-22','色彩','しきさい','색채; 색감; 사상적 성격','物の色や色の組み合わせ。また、比喩的に思想・性格などに表れる特徴。','この作品は鮮やかな色彩と強い社会批判の要素を併せ持っている。','이 작품은 선명한 색채와 강한 사회 비판 요소를 함께 지니고 있다.'),
('n1-3599','2027-01-22','情緒','じょうしょ','정서; 감정의 분위기','人の心に生じるさまざまな感情。また、ある場所・作品などが持つ感情的な趣。','古い町並みには、近代的な都市にはない独特の情緒が残っている。','오래된 거리에는 현대 도시에는 없는 독특한 정서가 남아 있다.'),
('n1-3600','2027-01-22','落下','らっか','낙하; 떨어짐','高い所にある物が低い所へ落ちること。','強風で看板が落下する危険があるため、周辺への立ち入りが禁止された。','강풍으로 간판이 낙하할 위험이 있어 주변 출입이 금지되었다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3601','2027-01-23','飼育','しいく','사육; 길러 기름','動物を人の管理下で飼い、育てること。','研究施設では動物を飼育する環境について厳しい基準が設けられている。','연구시설에서는 동물을 사육하는 환경에 엄격한 기준이 마련되어 있다.'),
('n1-3602','2027-01-23','宿命','しゅくめい','숙명; 피하기 어려운 운명','生まれた時から定められているかのように、避けることができない運命。','変化への対応は、技術企業にとって避けられない宿命とも言える。','변화에 대한 대응은 기술 기업에게 피할 수 없는 숙명이라고도 할 수 있다.'),
('n1-3603','2027-01-23','斜面','しゃめん','사면; 비탈면','水平ではなく、傾いている地面・面。','大雨が続いたため、山の斜面で土砂崩れが起きる危険が高まっている。','폭우가 계속돼 산비탈에서 산사태가 일어날 위험이 높아지고 있다.'),
('n1-3604','2027-01-23','生計','せいけい','생계; 생활을 유지하는 수단','生活を維持していくための収入・手段や暮らし向き。','退職後は小さな店を経営して生計を立てている。','퇴직 후에는 작은 가게를 운영하며 생계를 꾸리고 있다.'),
('n1-3605','2027-01-23','火星','かせい','화성','太陽系で太陽から四番目を公転する惑星。','将来の火星探査に向けて、長期間の有人滞在を想定した実験が進められている。','미래의 화성 탐사를 위해 장기간 유인 체류를 가정한 실험이 진행되고 있다.'),
('n1-3606','2027-01-23','見通し','みとおし','전망; 예상; 내다봄','将来の成り行きについて予測すること。また、その予測。遠くまで見渡せることの意味もある。','部品不足が解消される時期はまだ分からず、生産再開の見通しは立っていない。','부품 부족이 해소될 시기는 아직 알 수 없어 생산 재개의 전망이 서지 않았다.'),
('n1-3607','2027-01-23','勤務','きんむ','근무','職場に属し、定められた仕事や職務に従事すること。','彼は本社勤務を経て、今年から海外支社で働くことになった。','그는 본사 근무를 거쳐 올해부터 해외 지사에서 일하게 되었다.'),
('n1-3608','2027-01-23','人質','ひとじち','인질; 볼모','相手に要求を受け入れさせるなどの目的で、身柄を拘束されている人。','犯人は人質を解放する条件として、警察に複数の要求を突き付けた。','범인은 인질을 석방하는 조건으로 경찰에 여러 요구를 제시했다.'),
('n1-3609','2027-01-23','真実','しんじつ','진실; 사실','偽りのない本当の事実。','複数の証言を照合しなければ、事件の真実にはたどり着けない。','여러 증언을 대조하지 않으면 사건의 진실에 도달할 수 없다。'),
('n1-3610','2027-01-23','緊急','きんきゅう','긴급','事態が重大で、すぐに対応する必要があること。','システム障害が発生したため、担当者を集めて緊急の対策会議を開いた。','시스템 장애가 발생해 담당자를 모아 긴급 대책 회의를 열었다.'),
('n1-3611','2027-01-23','他方','たほう','한편; 다른 한편으로는','一方とは異なる側面や立場を示す語。文章では『他方、〜』の形で対照を示すことが多い。','在宅勤務には通勤時間を減らせる利点がある。他方、社員同士の交流が減るという課題もある。','재택근무에는 통근 시간을 줄일 수 있다는 장점이 있다. 한편 직원 간 교류가 줄어든다는 과제도 있다.'),
('n1-3612','2027-01-23','孤独','こどく','고독; 외로움','周囲とのつながりがなく一人であること、またはそのように感じて寂しい状態。','在宅勤務が長期化すると、人によっては孤独を感じやすくなる。','재택근무가 장기화되면 사람에 따라 고독을 느끼기 쉬워질 수 있다.'),
('n1-3613','2027-01-23','大幅','おおはば','대폭; 큰 폭','変化・増減・修正などの程度や範囲が非常に大きいこと。','業務を自動化した結果、処理時間を大幅に短縮できた。','업무를 자동화한 결과 처리 시간을 대폭 단축할 수 있었다.'),
('n1-3614','2027-01-23','堂々','どうどう','당당하게; 위풍당당하게; 거리낌 없이','態度や姿が立派で自信に満ちているさま。また、人目を恐れず公然と行うさま。','緊張していたはずなのに、彼は大勢の聴衆の前で堂々と発表した。','긴장했을 텐데도 그는 많은 청중 앞에서 당당하게 발표했다.'),
('n1-3615','2027-01-23','正常','せいじょう','정상; 이상 없음','異常や故障がなく、本来あるべき正しい状態であること。','再起動後はシステムが正常に動作していることを確認できた。','재시작 후에는 시스템이 정상적으로 작동하는 것을 확인할 수 있었다.'),
('n1-3616','2027-01-23','台無し','だいなし','엉망이 됨; 망침; 헛수고가 됨','それまでの価値・努力・良い状態などが損なわれ、役に立たなくなること。','最後の確認を怠ったせいで、それまでの丁寧な作業が台無しになってしまった。','마지막 확인을 소홀히 한 탓에 그동안의 꼼꼼한 작업이 엉망이 되어 버렸다.'),
('n1-3617','2027-01-23','行為','こうい','행위','人が意思をもって行う行動。','他人の個人情報を無断で公開する行為は認められない。','타인의 개인정보를 무단으로 공개하는 행위는 용납될 수 없다。'),
('n1-3618','2027-01-23','指摘','してき','지적','問題点などを具体的に取り上げて示すこと。','専門家は報告書のデータに矛盾があると指摘した。','전문가는 보고서의 데이터에 모순이 있다고 지적했다。'),
('n1-3619','2027-01-23','対応','たいおう','대응; 대처; 응대','状況や相手に応じて適切に処置・応答すること。','問い合わせが急増したため、担当者を増やして対応することになった。','문의가 급증하여 담당자를 늘려 대응하기로 했다。'),
('n1-3620','2027-01-23','確保','かくほ','확보','必要なものを確実に手に入れ、使える状態にしておくこと。','災害時でも通信手段を確保できるよう、複数の回線を用意している。','재해 시에도 통신 수단을 확보할 수 있도록 여러 회선을 준비하고 있다。'),
('n1-3621','2027-01-24','支持','しじ','지지','人や意見、方針などに賛成し、その立場を支えること。','その政策は若い世代から幅広い支持を集めている。','그 정책은 젊은 세대로부터 폭넓은 지지를 얻고 있다。'),
('n1-3622','2027-01-24','認識','にんしき','인식','物事の内容や性質を知り、そうであると理解すること。','担当者間で問題の認識に差があったため、対応方針がなかなか定まらなかった。','담당자들 사이에 문제 인식의 차이가 있어 대응 방침이 쉽게 정해지지 않았다。'),
('n1-3623','2027-01-24','監視','かんし','감시; 주시','異常や違反などがないか、注意して継続的に見守ること。','システムは二十四時間監視され、異常が検知されると担当者に通知される。','시스템은 24시간 감시되며 이상이 감지되면 담당자에게 통지된다。'),
('n1-3624','2027-01-24','上昇','じょうしょう','상승; 오름','位置・数値・程度などが上がること。','原材料価格の上昇が続けば、製品価格の見直しも避けられない。','원재료 가격 상승이 계속되면 제품 가격 조정도 피하기 어렵다。'),
('n1-3625','2027-01-24','説得','せっとく','설득','理由や事情を説明して、相手を納得させること。','計画の必要性を数字で示したことで、反対していた役員を説得できた。','계획의 필요성을 수치로 제시함으로써 반대하던 임원을 설득할 수 있었다。'),
('n1-3626','2027-01-24','配置','はいち','배치; 배치 상태','人や物を、それぞれの役割や目的に合う位置へ割り当てて置くこと。','来場者の安全を確保するため、入口ごとに警備員を配置した。','방문객의 안전을 확보하기 위해 입구마다 경비원을 배치했다。'),
('n1-3627','2027-01-24','運命','うんめい','운명; 운명적인 결과','人の意思を超えて将来の成り行きを決めると考えられる力、またはその成り行き。','偶然の出会いがその後の人生を大きく変え、本人はそれを運命だと感じた。','우연한 만남이 이후의 인생을 크게 바꾸었고 본인은 그것을 운명이라고 느꼈다。'),
('n1-3628','2027-01-24','映像','えいぞう','영상; 화면에 비친 상','映画・テレビ・カメラなどによって画面に映し出される像や、その記録。','防犯カメラの映像を確認したところ、不審な人物が建物に入る様子が記録されていた。','방범카메라 영상을 확인하자 수상한 인물이 건물에 들어가는 모습이 기록되어 있었다.'),
('n1-3629','2027-01-24','復活','ふっかつ','부활; 재개; 회복','一度失われたり衰えたりしたものが、再び元の状態や活動を取り戻すこと。死者が生き返る意でも用いる。','利用者の要望を受け、廃止されていた夜間便が来月から復活する。','이용자들의 요청을 받아 폐지됐던 야간편이 다음 달부터 부활한다.'),
('n1-3630','2027-01-24','展示','てんじ','전시','品物や作品などを、人に見せるために並べて公開すること。','博物館では、発掘された資料を年代順に展示している。','박물관에서는 발굴된 자료를 연대순으로 전시하고 있다.'),
('n1-3631','2027-01-24','昇進','しょうしん','승진','職場で現在より高い役職や地位に上がること。','管理職への昇進を機に、チーム全体の成果にも責任を持つ立場になった。','관리직으로 승진하면서 팀 전체의 성과에도 책임을 지는 입장이 되었다.'),
('n1-3632','2027-01-24','創造','そうぞう','창조; 창출','それまで存在しなかった新しいものや価値を作り出すこと。','既存の技術を組み合わせることで、新しい価値を創造することが期待されている。','기존 기술을 조합해 새로운 가치를 창출하는 것이 기대되고 있다.'),
('n1-3633','2027-01-24','部門','ぶもん','부문; 부서','組織や活動の全体を、役割や分野によって分けた一つの部分。','売上の伸びが最も大きかったのは、海外事業部門だった。','매출 증가 폭이 가장 컸던 것은 해외 사업 부문이었다.'),
('n1-3634','2027-01-24','優先','ゆうせん','우선; 우선시함','他のものより先に扱ったり、重要なものとして取り扱ったりすること。','限られた予算の中では、安全性に関わる改修を優先すべきだ。','한정된 예산 안에서는 안전성과 관련된 보수를 우선해야 한다.'),
('n1-3635','2027-01-24','連中','れんじゅう','무리; 사람들; 녀석들','同じ仲間に属する人々をまとめていう口語的な表現。文脈によっては軽い親しみや軽蔑を含む。','いつもの連中と久しぶりに集まり、学生時代の話で盛り上がった。','늘 어울리던 사람들과 오랜만에 모여 학창 시절 이야기로 즐거운 시간을 보냈다.'),
('n1-3636','2027-01-24','屋敷','やしき','저택; 저택과 그 부지','比較的大きな住宅。また、古くは住宅とそれに付属する庭や敷地を含めていう。','江戸時代の武家屋敷が保存され、現在は一般に公開されている。','에도 시대의 무사 저택이 보존되어 현재는 일반에 공개되고 있다.'),
('n1-3637','2027-01-24','感染','かんせん','감염','病原体が人や動物などの体内に入り、増殖すること。また、コンピューターウイルスなどが広がる場合にもいう。','感染を防ぐため、症状のある人には自宅で休むよう呼びかけている。','감염을 막기 위해 증상이 있는 사람에게는 집에서 쉬도록 안내하고 있다.'),
('n1-3638','2027-01-24','兵器','へいき','병기; 무기 체계','戦闘や軍事行動に用いる武器・装備・機械などの総称。','新型兵器の開発をめぐり、国際社会では規制の必要性が議論されている。','신형 병기 개발을 둘러싸고 국제사회에서는 규제 필요성이 논의되고 있다.'),
('n1-3639','2027-01-24','看護','かんご','간호','病気やけがをした人の状態を観察し、治療や生活を支えるために世話をすること。','高齢化に伴い、医療だけでなく在宅看護への需要も増えている。','고령화에 따라 의료뿐 아니라 재택 간호에 대한 수요도 늘고 있다.'),
('n1-3640','2027-01-24','死刑','しけい','사형; 사형제','犯罪に対する刑罰として、受刑者の生命を奪う刑。','死刑制度の存廃をめぐって、国内でも長年議論が続いている。','사형제도의 존폐를 둘러싸고 국내에서도 오랫동안 논의가 이어지고 있다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3641','2027-01-25','素材','そざい','소재; 재료','物を作るもとになる材料。また、作品・記事などの題材となるもの。','環境への負荷が少ない新素材の開発が、各国で進められている。','환경 부담이 적은 신소재 개발이 각국에서 진행되고 있다.'),
('n1-3642','2027-01-25','惑星','わくせい','행성','恒星の周囲を公転する、十分な質量を持つ天体。','観測技術の進歩によって、太陽系の外にも多くの惑星が発見されている。','관측 기술의 발전으로 태양계 밖에서도 많은 행성이 발견되고 있다.'),
('n1-3643','2027-01-25','背後','はいご','뒤; 배후; 배경','人や物の後ろ。また、表面には現れない事情・勢力・背景。','事件の背後に組織的な資金提供があった可能性も含めて捜査が進められている。','사건 배후에 조직적인 자금 제공이 있었을 가능성까지 포함해 수사가 진행되고 있다.'),
('n1-3644','2027-01-25','少数','しょうすう','소수; 적은 수','数や人数が少ないこと。また、多数に対して人数の少ない側。','少数の意見であっても、合理的な根拠があれば十分に検討すべきだ。','소수 의견이라도 합리적인 근거가 있다면 충분히 검토해야 한다.'),
('n1-3645','2027-01-25','同志','どうし','동지; 뜻을 같이하는 사람','同じ目的・理想・信念を持ち、行動を共にする人。','同じ理念を持つ同志と出会ったことが、活動を続ける大きな支えになった。','같은 이념을 가진 동지를 만난 것이 활동을 계속하는 큰 힘이 되었다.'),
('n1-3646','2027-01-25','処置','しょち','처치; 조치; 처리','状況に応じて必要な対応をすること。特に医療では、けがや病気に対して必要な手当てをすること。','けが人には現場で応急処置を行った後、すぐに病院へ搬送した。','부상자에게 현장에서 응급 처치를 한 뒤 곧바로 병원으로 이송했다.'),
('n1-3647','2027-01-25','中毒','ちゅうどく','중독; 중독 상태','毒物などによって身体に異常が起こること。また、物質・行為・思想などに過度に依存して離れにくくなる状態。','加熱が不十分な食品を食べると、食中毒を起こす危険がある。','가열이 불충분한 음식을 먹으면 식중독을 일으킬 위험이 있다.'),
('n1-3648','2027-01-25','直面','ちょくめん','직면; 맞닥뜨림','避けることのできない問題・困難・状況などに直接向き合うこと。','多くの地方自治体が、人口減少と財政難という二つの課題に直面している。','많은 지방자치단체가 인구 감소와 재정난이라는 두 과제에 직면해 있다.'),
('n1-3649','2027-01-25','改良','かいりょう','개량; 개선','既存の物の悪い点を直し、品質・機能・性能などをより良くすること。','利用者の意見をもとに製品を改良し、操作性と耐久性を高めた。','이용자 의견을 바탕으로 제품을 개량해 조작성과 내구성을 높였다.'),
('n1-3650','2027-01-25','出生','しゅっしょう','출생; 태어남','人がこの世に生まれること。『しゅっせい』とも読む。','出生数の減少が続き、地域の学校再編が大きな課題になっている。','출생아 수 감소가 계속되면서 지역 학교 재편이 큰 과제가 되고 있다.'),
('n1-3651','2027-01-25','放射','ほうしゃ','방사; 방출','中心から周囲へ向かって、光・熱・粒子・エネルギーなどを出すこと。','装置から放射される電磁波が基準値を超えないか定期的に測定している。','장치에서 방사되는 전자파가 기준치를 넘지 않는지 정기적으로 측정하고 있다.'),
('n1-3652','2027-01-25','充実','じゅうじつ','충실; 내실; 알참','内容が十分に備わり、質的にも満たされていること。また、その状態にすること。','研修内容を充実させるため、実務に近い演習を大幅に増やした。','연수 내용을 충실하게 하기 위해 실무에 가까운 연습을 크게 늘렸다.'),
('n1-3653','2027-01-25','本文','ほんぶん','본문','文書・手紙・記事・書籍などで、見出しや注記ではなく中心となる文章部分。','メールの件名だけでは内容が分からないので、本文を最後まで確認してください。','메일 제목만으로는 내용을 알 수 없으니 본문을 끝까지 확인해 주세요.'),
('n1-3654','2027-01-25','一面','いちめん','일면; 한 측면; 온통','物事の一つの側面。また、ある範囲全体に広がっている状態を表すこともある。','厳しい人に見えるが、困っている人を放っておけない一面もある。','엄격한 사람처럼 보이지만 곤란한 사람을 그냥 두지 못하는 일면도 있다.'),
('n1-3655','2027-01-25','航海','こうかい','항해','船で海や大きな水域を航行すること。また、その旅。','長い航海に備えて、船には十分な食料と燃料が積み込まれた。','긴 항해에 대비해 배에는 충분한 식량과 연료가 실렸다.'),
('n1-3656','2027-01-25','告白','こくはく','고백; 털어놓음','心の中に隠していた気持ち・事実・秘密などを、正直に打ち明けること。','彼は長い間隠していた事実を家族に告白し、ようやく気持ちが楽になった。','그는 오랫동안 숨겨 왔던 사실을 가족에게 고백하고서야 마음이 한결 편해졌다.'),
('n1-3657','2027-01-25','大金','たいきん','큰돈; 거액','非常に多額の金銭。','十分な説明もない投資話に、いきなり大金を預けるのは危険だ。','충분한 설명도 없는 투자 이야기에 갑자기 큰돈을 맡기는 것은 위험하다.'),
('n1-3658','2027-01-25','結成','けっせい','결성; 조직함','共通の目的を持つ人々を集め、団体・組織・チームなどを作ること。','新規事業を検討するため、各部署からメンバーを集めて専門チームを結成した。','신규 사업을 검토하기 위해 각 부서에서 구성원을 모아 전문 팀을 결성했다.'),
('n1-3659','2027-01-25','同情','どうじょう','동정; 공감하며 안타까워함','他人の苦しみや不幸を自分のことのように感じ、かわいそうに思うこと。','同情するだけでなく、相手が本当に必要としている支援を考えることが大切だ。','동정하는 데 그치지 않고 상대가 정말 필요로 하는 지원을 생각하는 것이 중요하다.'),
('n1-3660','2027-01-25','末期','まっき','말기; 마지막 시기','ある時代・期間・病気などの終わりに近い時期。','江戸時代末期には、国内外の情勢が大きく変化した。','에도 시대 말기에는 국내외 정세가 크게 변했다.'),
('n1-3661','2027-01-26','類似','るいじ','유사; 비슷함','二つ以上の物事が性質・形・内容などの点でよく似ていること。','過去にも類似した障害が起きていないか、運用記録を調べることにした。','과거에도 유사한 장애가 발생한 적이 없는지 운영 기록을 조사하기로 했다.'),
('n1-3662','2027-01-26','脚本','きゃくほん','각본; 대본; 시나리오','映画・演劇・ドラマなどのせりふ、場面、動作などを記した台本。','原作小説を二時間の映画にするため、脚本では一部の場面が大きく変更された。','원작 소설을 두 시간짜리 영화로 만들기 위해 각본에서는 일부 장면이 크게 변경되었다.'),
('n1-3663','2027-01-26','幹部','かんぶ','간부; 핵심 관리자','組織・団体の中で中心的な地位にあり、運営や意思決定を担う人。','経営幹部は来年度の事業方針について三日間にわたり議論した。','경영 간부들은 내년도 사업 방침에 대해 사흘 동안 논의했다.'),
('n1-3664','2027-01-26','旅客','りょかく','여객; 승객','列車・船・航空機などを利用して移動する客。『りょきゃく』とも読む。','連休中は旅客が増えるため、鉄道会社は臨時列車を運行する。','연휴에는 여객이 늘기 때문에 철도회사는 임시 열차를 운행한다.'),
('n1-3665','2027-01-26','意地','いじ','고집; 오기; 자존심','自分の考えを簡単には曲げまいとする気持ち。また、困難でもやり通そうとする強い気持ちや誇り。','意地を張って一人で抱え込まず、難しいときは周囲に助けを求めたほうがいい。','고집을 부리며 혼자 떠안지 말고 어려울 때는 주변에 도움을 요청하는 편이 좋다.'),
('n1-3666','2027-01-26','上位','じょうい','상위; 높은 순위','順位・地位・階層・分類などで、より高い位置にあること。','検索結果の上位に表示されるからといって、必ずしも内容が正確とは限らない。','검색 결과 상위에 표시된다고 해서 반드시 내용이 정확한 것은 아니다.'),
('n1-3667','2027-01-26','公演','こうえん','공연; 공개 상연','音楽・演劇・舞踊などを観客の前で公開して行うこと。また、その催し。','海外公演の成功を受け、同じ作品を国内でも再演することが決まった。','해외 공연의 성공을 계기로 같은 작품을 국내에서도 재공연하기로 결정했다.'),
('n1-3668','2027-01-26','洪水','こうずい','홍수; 범람','大雨などによって川の水が大幅に増え、周囲へあふれること。また、大量のものが一気に押し寄せる比喩にも使う。','集中豪雨による洪水で道路が冠水し、多くの住民が避難した。','집중호우로 인한 홍수로 도로가 침수되어 많은 주민이 대피했다.'),
('n1-3669','2027-01-26','最善','さいぜん','최선; 가장 좋은 방법','考えられる選択肢の中で最も良いこと。また、できる限りの力を尽くすこと。','完全な解決が難しくても、今できる最善の方法を選ぶしかない。','완전한 해결이 어려워도 지금 할 수 있는 최선의 방법을 선택할 수밖에 없다.'),
('n1-3670','2027-01-26','乗り換え','のりかえ','환승; 갈아타기','利用している列車・バスなどを降り、別の路線や交通手段に乗り継ぐこと。','この駅で地下鉄に乗り換えれば、目的地まで最短で行ける。','이 역에서 지하철로 환승하면 목적지까지 가장 빨리 갈 수 있다.'),
('n1-3671','2027-01-26','貧乏','びんぼう','가난; 빈곤함','財産・収入が少なく、生活に十分な余裕がないこと。','若い頃は貧乏だったが、読書だけは欠かさなかったという。','젊은 시절에는 가난했지만 독서만큼은 거르지 않았다고 한다.'),
('n1-3672','2027-01-26','あっさり','あっさり','담백하게; 쉽게; 미련 없이','味・性格などがしつこくなく淡泊なさま。また、意外なほど簡単に物事が進むさま。','難航すると予想された交渉は、双方が条件を譲ったことで意外にあっさりまとまった。','난항이 예상됐던 협상은 양측이 조건을 양보하면서 의외로 쉽게 타결됐다.'),
('n1-3673','2027-01-26','観覧','かんらん','관람','展示・公演・競技などを見て楽しむこと。','特別展を観覧するには事前予約が必要です。','특별전을 관람하려면 사전 예약이 필요합니다.'),
('n1-3674','2027-01-26','不審','ふしん','수상함; 의심스러움; 의혹','様子・行動・事情などが怪しく、疑わしいと感じられること。','駅で不審な荷物を見つけた場合は、触れずに係員へ知らせてください。','역에서 수상한 짐을 발견한 경우 손대지 말고 직원에게 알려 주세요.'),
('n1-3675','2027-01-26','向き','むき','방향; 적합함; ~용','向いている方向。また、人や用途に適していることを表す。','この教材は説明が丁寧なので、初めて学ぶ人向きだ。','이 교재는 설명이 친절해서 처음 배우는 사람에게 적합하다.'),
('n1-3676','2027-01-26','上がり','あがり','끝; 완료; 수익; 올라감','『上がる』の名詞形で、物事の終了・出来上がり・収入や利益・上昇など、文脈によって複数の意味を持つ。','この仕事は最後の確認が終われば、今日はもう上がりだ。','이 일은 마지막 확인만 끝나면 오늘은 이제 끝이다.'),
('n1-3677','2027-01-26','組み合わせ','くみあわせ','조합; 결합; 짝','複数の物・要素・人などを一緒にして一つのまとまりにすること。また、その取り合わせ。','異なる技術の組み合わせによって、従来にはなかったサービスが生まれた。','서로 다른 기술의 조합으로 기존에는 없던 서비스가 탄생했다.'),
('n1-3678','2027-01-26','無能','むのう','무능; 능력이 없음','必要な能力・才能がなく、役割や仕事を十分に果たせないさま。','一度の失敗だけで相手を無能だと決めつけるのは適切ではない。','한 번의 실패만으로 상대를 무능하다고 단정하는 것은 적절하지 않다.'),
('n1-3679','2027-01-26','無難','ぶなん','무난함; 탈이 없음','大きな欠点や危険がなく、問題なく済ませられるさま。','初対面の場では、まず無難な話題から会話を始める人が多い。','첫 만남에서는 우선 무난한 화제로 대화를 시작하는 사람이 많다.'),
('n1-3680','2027-01-26','とんだ','とんだ','뜻밖의; 터무니없는; 아주 심한','思いがけずひどい、またはとんでもないという意味を表す連体的な語。','とんだ災難に巻き込まれてしまった。','뜻밖의 큰 재난에 휘말리고 말았다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3681','2027-01-27','同感','どうかん','동감; 같은 생각','他人の意見・感情に、自分も同じように感じること。','その指摘には私も同感で、今の手順には改善の余地があると思う。','그 지적에는 나도 동감이며 현재 절차에는 개선할 여지가 있다고 생각한다.'),
('n1-3682','2027-01-27','有益','ゆうえき','유익; 도움이 됨','利益・効果があり、役に立つさま。','失敗の原因を共有することは、再発防止を考える上で非常に有益だ。','실패 원인을 공유하는 것은 재발 방지를 생각하는 데 매우 유익하다.'),
('n1-3683','2027-01-27','不調','ふちょう','부진; 상태가 좋지 않음','体調・機械・業績・交渉などの状態がよくなく、思うように進まないさま。','システムの不調が続いたため、予防保守の計画を見直すことになった。','시스템 상태 불량이 계속되어 예방보수 계획을 재검토하게 되었다.'),
('n1-3684','2027-01-27','頻繁','ひんぱん','빈번함; 잦음','同じことが短い間隔で何度も起こるさま。','仕様変更が頻繁だと、開発側の負担が大きくなる。','사양 변경이 빈번하면 개발 측의 부담이 커진다.'),
('n1-3685','2027-01-27','良好','りょうこう','양호함; 상태가 좋음','状態・関係・成績・品質などがよく、問題が少ないさま。','試験運転の結果、システムは良好な状態で稼働している。','시험 운전 결과 시스템은 양호한 상태로 가동되고 있다.'),
('n1-3686','2027-01-27','未熟','みじゅく','미숙함; 미성숙','経験・技術・精神などがまだ十分に発達しておらず、不十分なさま。','まだ未熟な点は多いが、経験を積みながら改善していきたい。','아직 미숙한 점이 많지만 경험을 쌓으며 개선해 가고 싶다.'),
('n1-3687','2027-01-27','推理','すいり','추리; 추론','分かっている事実を手がかりに、まだ分からない事柄を論理的に推し量ること。','残された記録から当時何が起きたのかを推理するのが、この作品の面白さだ。','남아 있는 기록으로 당시 무슨 일이 있었는지 추리하는 것이 이 작품의 재미다.'),
('n1-3688','2027-01-27','生死','せいし','생사; 삶과 죽음','生きることと死ぬこと。命にかかわる重大な状態。','災害直後の数時間は、被災者の生死を左右する重要な時間だ。','재난 직후 몇 시간은 피해자의 생사를 좌우하는 중요한 시간이다.'),
('n1-3689','2027-01-27','動力','どうりょく','동력; 기계를 움직이는 힘','機械・乗り物などを動かすために利用されるエネルギー・力。','この装置は電力ではなく圧縮空気を動力として作動する。','이 장치는 전력이 아니라 압축 공기를 동력으로 작동한다.'),
('n1-3690','2027-01-27','補充','ほじゅう','보충; 부족한 것을 채움','不足した人員・物資・数量などを追加して満たすこと。','在庫が一定数を下回ると、自動的に商品を補充する仕組みになっている。','재고가 일정 수 이하로 내려가면 자동으로 상품을 보충하는 구조다.'),
('n1-3691','2027-01-27','化石','かせき','화석','昔の生物の遺体・痕跡などが地層中に残ったもの。','発見された化石を分析した結果、この地域には古くから大型動物が生息していたことが分かった。','발견된 화석을 분석한 결과 이 지역에 예전부터 대형 동물이 서식했다는 사실이 밝혀졌다.'),
('n1-3692','2027-01-27','募金','ぼきん','모금; 기부금을 모음','寄付金・義援金などを広く呼びかけて集めること。','被災地を支援するため、駅前で募金活動が行われた。','재해 지역을 지원하기 위해 역 앞에서 모금 활동이 실시되었다.'),
('n1-3693','2027-01-27','山岳','さんがく','산악; 높고 험한 산들','高く険しい山々。また、山に関係する地域・活動。','山岳地帯では天候が急変しやすいため、十分な装備が必要だ。','산악 지대에서는 날씨가 급변하기 쉬워 충분한 장비가 필요하다.'),
('n1-3694','2027-01-27','風習','ふうしゅう','풍습; 오래된 생활 관습','ある地域・社会に昔から受け継がれている生活上の習慣・ならわし。','地域ごとに異なる風習を理解することは、文化を学ぶ上で重要だ。','지역마다 다른 풍습을 이해하는 것은 문화를 배우는 데 중요하다.'),
('n1-3695','2027-01-27','原油','げんゆ','원유','地下から採掘されたままで、まだ精製されていない石油。','原油価格の上昇が輸送費や製品価格に影響を与えている。','원유 가격 상승이 운송비와 제품 가격에 영향을 주고 있다.'),
('n1-3696','2027-01-27','保育','ほいく','보육','乳幼児などを保護し、生活面を世話しながら育てること。','共働き世帯の増加に伴い、保育サービスへの需要が高まっている。','맞벌이 가구 증가에 따라 보육 서비스 수요가 높아지고 있다.'),
('n1-3697','2027-01-27','電線','でんせん','전선; 전깃줄','電気を通すために用いる金属製の線。','台風で電線が切れ、一部の地域で停電が発生した。','태풍으로 전선이 끊어져 일부 지역에서 정전이 발생했다.'),
('n1-3698','2027-01-27','陶器','とうき','도기; 도자기','粘土を成形し、比較的低い温度で焼いて作る器物。広く陶磁器類を指すこともある。','この地方では伝統的な技法で作られた陶器が土産物として人気だ。','이 지방에서는 전통 기법으로 만든 도기가 기념품으로 인기가 많다.'),
('n1-3699','2027-01-27','教材','きょうざい','교재; 학습 자료','教育・学習のために用いる教科書・資料・映像など。','授業では教科書だけでなく、新聞記事も教材として活用している。','수업에서는 교과서뿐 아니라 신문 기사도 교재로 활용하고 있다.'),
('n1-3700','2027-01-27','同居','どうきょ','동거; 함께 거주함','同じ家・住居で一緒に暮らすこと。','両親と同居することになり、家の一部を改装した。','부모님과 함께 살게 되어 집 일부를 개조했다.'),
('n1-3701','2027-01-28','交互','こうご','교대로; 번갈아','二つ以上のものが順番に入れ替わること。','二人は一時間ずつ交互に運転して長距離を移動した。','두 사람은 한 시간씩 번갈아 운전하며 장거리를 이동했다.'),
('n1-3702','2027-01-28','送金','そうきん','송금','銀行などを通じて、離れた相手に金銭を送ること。','海外へ送金する際には手数料と為替レートを確認したほうがよい。','해외로 송금할 때는 수수료와 환율을 확인하는 편이 좋다.'),
('n1-3703','2027-01-28','立体','りったい','입체; 입체물','縦・横・高さの三つの方向に広がりを持つ物体。','設計図だけでなく立体模型を使うと、完成後の形を想像しやすい。','설계도뿐 아니라 입체 모형을 사용하면 완성 후 형태를 상상하기 쉽다.'),
('n1-3704','2027-01-28','肥料','ひりょう','비료; 거름','植物の生育をよくするため、土壌などに与える栄養分を含む物質。','作物の種類に合わせて肥料の量を調整しなければならない。','작물 종류에 맞춰 비료의 양을 조절해야 한다.'),
('n1-3705','2027-01-28','戦力','せんりょく','전력; 싸울 수 있는 능력','戦闘を行うための総合的な力。また、競技などで勝敗に影響する有力な人員・能力。','経験豊富な選手の復帰は、チームにとって大きな戦力になる。','경험 많은 선수의 복귀는 팀에 큰 전력이 된다.'),
('n1-3706','2027-01-28','家計','かけい','가계; 가정의 수입과 지출','家庭における収入・支出などの経済状態や、そのやりくり。','物価の上昇が続き、家計への負担が以前より大きくなっている。','물가 상승이 계속되어 가계 부담이 이전보다 커지고 있다.'),
('n1-3707','2027-01-28','富豪','ふごう','부호; 매우 큰 부자','非常に多くの財産を持つ人。','その富豪は私財を投じて、地域の教育施設を建設した。','그 부호는 사재를 들여 지역 교육 시설을 건설했다.'),
('n1-3708','2027-01-28','外来','がいらい','외래; 외부에서 들어옴','外部・外国から入ってくること。また、病院で入院せず診察を受けること。','外来植物の増加が地域の生態系に影響を及ぼしている。','외래 식물의 증가가 지역 생태계에 영향을 미치고 있다.'),
('n1-3709','2027-01-28','近郊','きんこう','근교; 도시 주변 지역','都市の中心部から比較的近い周辺地域。','都心の家賃が高いため、近郊から通勤する人も多い。','도심 집세가 비싸서 근교에서 통근하는 사람도 많다.'),
('n1-3710','2027-01-28','排水','はいすい','배수; 물을 빼냄','不要な水・たまった水を外へ流し出すこと。','大雨に備えて、道路の排水設備を点検する作業が行われた。','폭우에 대비해 도로 배수 설비를 점검하는 작업이 실시되었다.'),
('n1-3711','2027-01-28','化合','かごう','화합; 화학적으로 결합함','二つ以上の元素・物質が化学的に結びつき、別の性質を持つ物質になること。','水素と酸素が一定の条件で化合すると水が生じる。','수소와 산소가 일정한 조건에서 화합하면 물이 생긴다.'),
('n1-3712','2027-01-28','定年','ていねん','정년','勤務先の規定などによって、退職することと定められている年齢。','定年後も経験を生かして働き続ける人が増えている。','정년 후에도 경험을 살려 계속 일하는 사람이 늘고 있다.'),
('n1-3713','2027-01-28','天体','てんたい','천체','恒星・惑星・衛星など、宇宙空間に存在する物体。','望遠鏡を使えば、肉眼では見えない暗い天体も観測できる。','망원경을 사용하면 맨눈으로 보이지 않는 어두운 천체도 관측할 수 있다.'),
('n1-3714','2027-01-28','衣料','いりょう','의류; 의복 재료 및 옷','衣服や、その材料となる布地などの総称。','原材料費の上昇により、衣料品の価格も上がっている。','원재료비 상승으로 의류 제품 가격도 오르고 있다.'),
('n1-3715','2027-01-28','人情','にんじょう','인정; 사람의 정','人が自然に持つ感情。特に、他人への思いやり・情け・温かい気持ち。','昔ながらの商店街には、困った人を助ける人情が今も残っている。','옛 상점가에는 어려운 사람을 돕는 인정이 지금도 남아 있다.'),
('n1-3716','2027-01-28','高原','こうげん','고원','標高が高く、比較的平らで広い土地。','夏でも涼しい高原には、多くの観光客が避暑に訪れる。','여름에도 시원한 고원에는 많은 관광객이 피서를 온다.'),
('n1-3717','2027-01-28','地主','じぬし','지주; 토지 소유자','土地を所有している人。特に、その土地を他人に貸して収益を得る所有者。','再開発を進めるには、周辺の地主との合意形成が欠かせない。','재개발을 추진하려면 주변 토지 소유자와의 합의 형성이 필수적이다.'),
('n1-3718','2027-01-28','結核','けっかく','결핵','結核菌によって主に肺などに起こる感染症。','結核は適切な検査と治療を受ければ、治癒が期待できる病気である。','결핵은 적절한 검사와 치료를 받으면 치료를 기대할 수 있는 질병이다.'),
('n1-3719','2027-01-28','津波','つなみ','쓰나미; 지진해일','海底地震・火山活動などによって生じ、沿岸へ押し寄せる大規模な波。','強い地震を感じたら、津波警報を待たず高い場所へ避難することが重要だ。','강한 지진을 느끼면 쓰나미 경보를 기다리지 말고 높은 곳으로 대피하는 것이 중요하다.'),
('n1-3720','2027-01-28','原爆','げんばく','원자폭탄; 원폭','『原子爆弾』の略。核分裂のエネルギーを利用する爆弾。','資料館では原爆による被害と被爆者の証言が保存・展示されている。','자료관에는 원폭 피해와 피폭자의 증언이 보존·전시되어 있다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3721','2027-01-29','静止','せいし','정지; 움직이지 않음','動いていたものが止まること。また、動かない状態にあること。','映像を静止させて確認すると、画面の端に小さな異常が見つかった。','영상을 정지시켜 확인하니 화면 끝에서 작은 이상이 발견되었다.'),
('n1-3722','2027-01-29','体格','たいかく','체격; 몸집','身長・骨格・肉付きなどから見た身体全体のつくり。','彼は大柄な体格だが、動きは非常に素早い。','그는 큰 체격이지만 움직임은 매우 빠르다.'),
('n1-3723','2027-01-29','樹木','じゅもく','수목; 나무','木本植物の総称。幹や枝を持ち、長年にわたって生育する木。','公園では老朽化した樹木の安全点検が定期的に行われている。','공원에서는 노후한 수목의 안전 점검이 정기적으로 이루어지고 있다.'),
('n1-3724','2027-01-29','原文','げんぶん','원문','翻訳・要約・書き換えなどをする前の、もとの文章。','翻訳だけで意味が曖昧な場合は、原文を確認したほうがよい。','번역만으로 의미가 모호한 경우에는 원문을 확인하는 편이 좋다.'),
('n1-3725','2027-01-29','無言','むごん','무언; 말이 없음','何も言葉を発しないこと。','彼は質問に答えず、無言のまま部屋を出ていった。','그는 질문에 답하지 않고 아무 말 없이 방을 나갔다.'),
('n1-3726','2027-01-29','故人','こじん','고인; 세상을 떠난 사람','亡くなった人。','式典では故人の功績を振り返り、黙とうがささげられた。','식전에서는 고인의 공적을 되돌아보며 묵념을 올렸다.'),
('n1-3727','2027-01-29','味覚','みかく','미각','舌などで甘味・酸味・苦味などの味を感じる感覚。','体調によって味覚が変わり、普段と違う味に感じることもある。','몸 상태에 따라 미각이 달라져 평소와 다른 맛으로 느껴질 때도 있다.'),
('n1-3728','2027-01-29','残高','ざんだか','잔고; 남은 금액','口座・会計などで、差し引き後に残っている金額。','振り込みの前に口座の残高を確認した。','송금 전에 계좌 잔고를 확인했다.'),
('n1-3729','2027-01-29','堤防','ていぼう','제방; 둑','川・海などの水があふれるのを防ぐために、土・石・コンクリートなどで築く構造物。','大雨に備えて、老朽化した堤防の補強工事が進められている。','폭우에 대비해 노후한 제방의 보강 공사가 진행되고 있다.'),
('n1-3730','2027-01-29','野外','やがい','야외; 옥외','建物の外。特に、自然の中の開けた場所。','雨天の場合、野外イベントは体育館で実施される。','우천 시 야외 행사는 체육관에서 실시된다.'),
('n1-3731','2027-01-29','当人','とうにん','당사자 본인; 바로 그 사람','その事柄に直接関係している本人。','当人の同意がないまま個人情報を公開してはいけない。','당사자 본인의 동의 없이 개인정보를 공개해서는 안 된다.'),
('n1-3732','2027-01-29','時差','じさ','시차; 시간 차이','地域・国の標準時の差。また、出来事の発生時刻などの時間的なずれ。','海外との会議では時差を考慮して開始時刻を決める必要がある。','해외와의 회의는 시차를 고려해 시작 시간을 정할 필요가 있다.'),
('n1-3733','2027-01-29','転勤','てんきん','전근; 근무지 이동','同じ会社・組織の中で、勤務地が別の場所へ変わること。','来月から大阪支社へ転勤することになった。','다음 달부터 오사카 지사로 전근하게 되었다.'),
('n1-3734','2027-01-29','生育','せいいく','생육; 자라남','植物・動物などが成長し、育つこと。','今年は日照時間が長く、作物の生育が例年より早い。','올해는 일조 시간이 길어 작물 생육이 예년보다 빠르다.'),
('n1-3735','2027-01-29','耕作','こうさく','경작','田畑を耕し、作物を育てること。','高齢化により、耕作されなくなった農地が増えている。','고령화로 경작되지 않는 농지가 늘고 있다.'),
('n1-3736','2027-01-29','朗読','ろうどく','낭독; 소리 내어 읽음','文章・詩などを、聞き手に伝わるよう声に出して読むこと。','文学作品の朗読会には幅広い世代の参加者が集まった。','문학 작품 낭독회에는 다양한 세대의 참가자가 모였다.'),
('n1-3737','2027-01-29','学歴','がくれき','학력; 학업 경력','どの学校で学び、卒業したかなどの教育上の経歴。','採用では学歴だけでなく、実務経験や適性も重視している。','채용에서는 학력뿐 아니라 실무 경험과 적성도 중시하고 있다.'),
('n1-3738','2027-01-29','入賞','にゅうしょう','입상','競技・コンテストなどで、賞を受けられる順位・成績に入ること。','全国大会で入賞した作品は来月から市役所に展示される。','전국대회에서 입상한 작품은 다음 달부터 시청에 전시된다.'),
('n1-3739','2027-01-29','着席','ちゃくせき','착석; 자리에 앉음','自分の席について座ること。','開始時刻の五分前までに着席してください。','시작 시각 5분 전까지 착석해 주세요.'),
('n1-3740','2027-01-29','田園','でんえん','전원; 논밭이 펼쳐진 농촌','田畑が広がる、のどかな農村地域。また、その風景。','列車の窓から緑豊かな田園風景が一面に広がって見えた。','열차 창밖으로 푸른 전원 풍경이 한가득 펼쳐져 보였다.'),
('n1-3741','2027-01-30','出社','しゅっしゃ','출사; 회사에 출근함','勤務する会社へ行くこと。','明日は午前中だけ在宅勤務をし、午後から出社する予定だ。','내일은 오전만 재택근무를 하고 오후부터 회사에 출근할 예정이다.'),
('n1-3742','2027-01-30','歓声','かんせい','환호성; 기쁨의 함성','喜び・興奮などから大勢の人が上げる声。','決勝点が入った瞬間、観客席から大きな歓声が上がった。','결승골이 들어간 순간 관중석에서 큰 환호성이 터졌다.'),
('n1-3743','2027-01-30','根気','こんき','끈기; 인내력','物事を途中で投げ出さず、長く続ける気力。','複雑な資料を一つずつ確認するには相当な根気が必要だ。','복잡한 자료를 하나씩 확인하려면 상당한 끈기가 필요하다.'),
('n1-3744','2027-01-30','先着','せんちゃく','선착; 먼저 도착함','他の人より先に到着すること。『先着順』の形でも多く使う。','説明会は先着百名まで参加できる。','설명회는 선착순 100명까지 참가할 수 있다.'),
('n1-3745','2027-01-30','迅速','じんそく','신속; 매우 빠름','物事の処理・判断・行動などが非常に速いこと。','情報漏えいが疑われる場合は、被害を広げないため迅速な対応が必要だ。','정보 유출이 의심되는 경우 피해 확산을 막기 위해 신속한 대응이 필요하다.'),
('n1-3746','2027-01-30','壮大','そうだい','장대; 웅대; 규모가 매우 큼','規模・構想・景色などが非常に大きく、立派で迫力があるさま。','宇宙開発という壮大な計画を実現するには、長期的な資金と人材が必要だ。','우주 개발이라는 장대한 계획을 실현하려면 장기적인 자금과 인력이 필요하다.'),
('n1-3747','2027-01-30','神秘','しんぴ','신비; 불가사의함','人間の知識や通常の理屈では簡単に説明できない、不思議で奥深いこと。','深海にはまだ観測されていない生物が多く、生命の神秘を感じさせる。','심해에는 아직 관측되지 않은 생물이 많아 생명의 신비를 느끼게 한다.'),
('n1-3748','2027-01-30','強烈','きょうれつ','강렬함; 매우 강함','刺激・印象・作用などが非常に強いさま。','初めて会ったときの強烈な印象は、数年たった今でもよく覚えている。','처음 만났을 때의 강렬한 인상은 몇 년이 지난 지금도 잘 기억하고 있다.'),
('n1-3749','2027-01-30','健全','けんぜん','건전함; 건강하고 정상적임','心身・組織・考え方・経営などが健康で、偏りや問題がなく正常な状態にあるさま。','市場を健全に発展させるには、公正な競争を守る仕組みが必要だ。','시장을 건전하게 발전시키려면 공정한 경쟁을 지키는 장치가 필요하다.'),
('n1-3750','2027-01-30','気楽','きらく','마음 편함; 부담이 없음; 느긋함','心配・責任・緊張などが少なく、気持ちが楽であるさま。','結果を気にしすぎず、もう少し気楽に挑戦してみてもいいと思う。','결과를 너무 신경 쓰지 말고 조금 더 마음 편하게 도전해 봐도 좋다고 생각한다.'),
('n1-3751','2027-01-30','盛大','せいだい','성대함; 규모가 크고 화려함','行事・催しなどの規模が大きく、にぎやかで立派なさま。','創立百周年を記念する式典が、国内外から多くの来賓を招いて盛大に開かれた。','창립 100주년 기념식이 국내외 많은 내빈을 초청해 성대하게 열렸다.'),
('n1-3752','2027-01-30','未定','みてい','미정; 아직 정해지지 않음','予定・方法・担当などがまだ決まっていないこと。','公開日は未定だが、開発状況は毎月報告する予定だ。','공개일은 미정이지만 개발 상황은 매달 보고할 예정이다.'),
('n1-3753','2027-01-30','無意味','むいみ','무의미함; 의미 없음','意味・価値・効果などがないこと。','目的のない議論を続けても無意味だ。','목적 없는 논의를 계속해도 무의미하다.'),
('n1-3754','2027-01-30','携帯','けいたい','휴대; 휴대전화','物を身に付けて持ち歩くこと。また、『携帯電話』の略としても使う。','非常時に備えて、身分証明書と連絡先を携帯しておくとよい。','비상시에 대비해 신분증과 연락처를 휴대해 두는 것이 좋다.'),
('n1-3755','2027-01-30','兵士','へいし','병사; 군인','軍隊に所属し、軍事上の任務に従事する人。','戦争を経験した元兵士の証言が資料として保存されている。','전쟁을 경험한 전직 병사의 증언이 자료로 보존되어 있다.'),
('n1-3756','2027-01-30','着陸','ちゃくりく','착륙','航空機などが空中から地上へ降りること。','強風のため、飛行機は予定していた空港への着陸を断念した。','강풍 때문에 비행기는 예정했던 공항 착륙을 포기했다.'),
('n1-3757','2027-01-30','修行','しゅぎょう','수행; 기술을 닦는 훈련','精神・技能などを高めるために厳しい訓練・実践を重ねること。','彼は若い頃、職人として腕を磨くため各地で修行を重ねた。','그는 젊었을 때 장인으로서 실력을 닦기 위해 여러 지역에서 수련을 거듭했다.'),
('n1-3758','2027-01-30','破壊','はかい','파괴','物・組織・秩序などを壊し、正常に機能しない状態にすること。','無計画な開発が自然環境の破壊につながる可能性が指摘されている。','무계획한 개발이 자연환경 파괴로 이어질 가능성이 지적되고 있다.'),
('n1-3759','2027-01-30','収集','しゅうしゅう','수집','必要な物・情報などを集めること。','原因を特定するため、まず関連するログを収集する。','원인을 특정하기 위해 우선 관련 로그를 수집한다.'),
('n1-3760','2027-01-30','本名','ほんみょう','본명','芸名・筆名・通称などではない、本来の名前。','作家は長年ペンネームで活動し、本名を公表していなかった。','작가는 오랫동안 필명으로 활동하며 본명을 공개하지 않았다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3761','2027-01-31','課題','かだい','과제; 해결해야 할 문제','解決・検討すべき問題。また、学校などで与えられる学習上の仕事。','導入後の最大の課題は、現場の運用負担をどう減らすかである。','도입 후 가장 큰 과제는 현장의 운영 부담을 어떻게 줄일지다.'),
('n1-3762','2027-01-31','退職','たいしょく','퇴직','勤めている職場・職務を辞めること。','退職後も専門知識を生かし、非常勤の相談員として働いている。','퇴직 후에도 전문 지식을 살려 비상근 상담원으로 일하고 있다.'),
('n1-3763','2027-01-31','赤字','あかじ','적자','支出が収入を上回り、損失が出ている状態。また、その損失額。','利用者の減少が続き、路線は三年連続で赤字となった。','이용자 감소가 이어져 노선은 3년 연속 적자를 기록했다.'),
('n1-3764','2027-01-31','装飾','そうしょく','장식; 꾸밈','物・建物・文章などを美しく見せるために飾ること。また、その飾り。','会場は過度な装飾を避け、落ち着いた雰囲気にまとめられていた。','행사장은 과도한 장식을 피하고 차분한 분위기로 꾸며져 있었다.'),
('n1-3765','2027-01-31','退学','たいがく','퇴학; 자퇴','学校を途中で辞めること。また、学校側の処分によって辞めさせられること。','経済的な理由で退学を考える学生を支援する制度が設けられた。','경제적인 이유로 자퇴를 고민하는 학생을 지원하는 제도가 마련됐다.'),
('n1-3766','2027-01-31','脱出','だっしゅつ','탈출; 빠져나옴','危険な場所・拘束された状態・困難な状況などから抜け出すこと。','乗客は非常口から無事に機内を脱出した。','승객들은 비상구를 통해 무사히 기내에서 탈출했다.'),
('n1-3767','2027-01-31','徒歩','とほ','도보; 걸어서 감','乗り物を使わず、歩いて移動すること。','駅から会場までは徒歩で約十分かかる。','역에서 행사장까지는 도보로 약 10분 걸린다.'),
('n1-3768','2027-01-31','平方','へいほう','제곱; 평방','同じ数を二度掛け合わせること。また、面積の単位を表すときにも用いる語。','この部屋の面積はおよそ二十平方メートルだ。','이 방의 면적은 약 20제곱미터다.'),
('n1-3769','2027-01-31','街道','かいどう','가도; 주요 도로','昔から都市・地域を結ぶ主要な道路。','古い街道沿いには江戸時代の町並みが一部残っている。','옛 가도를 따라 에도 시대의 거리 풍경이 일부 남아 있다.'),
('n1-3770','2027-01-31','振動','しんどう','진동','物体が一定の位置を中心に繰り返し揺れ動くこと。','工事による振動が周辺の建物に影響していないか測定した。','공사로 인한 진동이 주변 건물에 영향을 주지 않는지 측정했다.'),
('n1-3771','2027-01-31','衣装','いしょう','의상; 무대 의상','身につける衣服。特に、舞台・映画・式典などで目的に合わせて着る服。','時代劇の衣装は当時の資料を参考にして制作された。','시대극 의상은 당시 자료를 참고해 제작되었다.'),
('n1-3772','2027-01-31','好意','こうい','호의; 좋은 감정','相手を好ましく思う気持ち。また、親切にしようとする気持ち。','相手の好意に甘えすぎず、きちんと感謝を伝えたい。','상대의 호의에 너무 기대지 말고 제대로 감사를 전하고 싶다.'),
('n1-3773','2027-01-31','幽霊','ゆうれい','유령; 귀신','死者の霊が、生前の姿などで現れるとされるもの。','古い旅館には幽霊が出るという噂がある。','오래된 여관에는 유령이 나온다는 소문이 있다.'),
('n1-3774','2027-01-31','人目','じんもく','남의 눈; 세간의 시선','人の目、または世間の人が見る目。現代の日常語では『ひとめ』と読むことが多い。','彼は人目を避けるように、裏口から建物を出た。','그는 남의 눈을 피하듯 뒷문으로 건물을 나갔다.'),
('n1-3775','2027-01-31','手数','てかず','수순 수; 손을 쓰는 횟수','囲碁・将棋などで手を指した回数。また、目的を達するまでに必要な動作・手順の数。','この手順なら作業の手数を減らして処理時間を短縮できる。','이 절차라면 작업 수순을 줄여 처리 시간을 단축할 수 있다.'),
('n1-3776','2027-01-31','装備','そうび','장비; 갖춤','目的に必要な器具・機械・機能などを備えること。また、その備品。','新型車には高度な安全装備が標準で付いている。','신형 차량에는 고도의 안전 장비가 기본으로 탑재되어 있다.'),
('n1-3777','2027-01-31','暴風','ぼうふう','폭풍; 매우 강한 바람','非常に激しく吹く風。','暴風の影響で鉄道の一部区間が運休となった。','폭풍의 영향으로 철도 일부 구간이 운휴했다.'),
('n1-3778','2027-01-31','爆弾','ばくだん','폭탄','爆薬を入れ、爆発によって大きな破壊力を生じさせる兵器・装置。','不審物が見つかり、爆弾処理班が現場を確認した。','수상한 물체가 발견되어 폭발물 처리반이 현장을 확인했다.'),
('n1-3779','2027-01-31','紳士','しんし','신사; 교양과 예의를 갖춘 남성','礼儀・教養を備えた上品な男性。また、男性を丁寧に指す語。','彼は誰に対しても丁寧に接する紳士的な人物だ。','그는 누구에게나 정중하게 대하는 신사적인 인물이다.'),
('n1-3780','2027-01-31','昆虫','こんちゅう','곤충','体が頭部・胸部・腹部に分かれ、通常三対の脚を持つ節足動物の一群。','気温の上昇により、この地域で見られる昆虫の種類も変化している。','기온 상승으로 이 지역에서 보이는 곤충 종류도 변하고 있다.'),
('n1-3781','2027-02-01','返答','へんとう','대답; 회답','質問・依頼・呼びかけなどに対して答えること。また、その答え。','先方から返答がないため、明日もう一度連絡する。','상대방에게서 답변이 없어 내일 다시 연락한다.'),
('n1-3782','2027-02-01','運送','うんそう','운송; 운반','人・荷物・商品などを車両・船・航空機などで目的地まで運ぶこと。','大型機器の運送には専門業者を利用することになった。','대형 장비 운송에는 전문 업체를 이용하기로 했다.'),
('n1-3783','2027-02-01','真珠','しんじゅ','진주','貝の体内に形成される、光沢を持つ丸い宝石。','その地域では真珠の養殖が重要な産業になっている。','그 지역에서는 진주 양식이 중요한 산업이 되어 있다.'),
('n1-3784','2027-02-01','仏像','ぶつぞう','불상','仏・菩薩などの姿を彫刻や像として表したもの。','寺の本堂には平安時代に作られた仏像が安置されている。','절 본당에는 헤이안 시대에 만들어진 불상이 모셔져 있다.'),
('n1-3785','2027-02-01','家出','いえで','가출','家族に告げず、または家に戻る意思を持たずに自宅を離れること。','未成年者の家出について家族から警察に相談が寄せられた。','미성년자의 가출에 대해 가족이 경찰에 상담을 요청했다.'),
('n1-3786','2027-02-01','夜行','やぎょう','야간 운행; 밤에 이동함','夜間に移動・運行すること。『夜行列車』『夜行バス』などの形でよく使う。','東京から大阪まで夜行バスで移動した。','도쿄에서 오사카까지 야간 버스로 이동했다.'),
('n1-3787','2027-02-01','短歌','たんか','단가; 일본의 31음 정형시','五・七・五・七・七の三十一音を基本とする日本の定型詩。','授業で四季を題材にした短歌を一首作った。','수업에서 사계를 주제로 단가 한 수를 지었다.'),
('n1-3788','2027-02-01','豊作','ほうさく','풍작','農作物がよく実り、例年より多く収穫できること。','天候に恵まれ、今年の米は近年にない豊作となった。','날씨가 좋아 올해 쌀은 근래 보기 드문 풍작이 되었다.'),
('n1-3789','2027-02-01','既婚','きこん','기혼','すでに結婚していること。','調査では回答者を未婚・既婚などの属性別に集計した。','조사에서는 응답자를 미혼·기혼 등의 속성별로 집계했다.'),
('n1-3790','2027-02-01','始発','しはつ','첫차; 첫 운행','その日の最初に出発する列車・バスなど。また、その最初の運行。','早朝の便に間に合うよう、始発の電車で空港へ向かった。','이른 아침 비행기를 타기 위해 첫 전철로 공항에 향했다.'),
('n1-3791','2027-02-01','守衛','しゅえい','수위; 경비원','施設の入口などで出入りを確認し、建物や敷地を警備する人。','夜間に入館する場合は、守衛に社員証を提示してください。','야간에 입관할 경우 수위에게 사원증을 제시해 주세요.'),
('n1-3792','2027-02-01','沸騰','ふっとう','비등; 끓음','液体が沸点に達し、内部から盛んに気泡が生じて気体になること。','水が沸騰したら火を弱め、さらに五分ほど加熱する。','물이 끓으면 불을 줄이고 5분 정도 더 가열한다.'),
('n1-3793','2027-02-01','水田','すいでん','논; 수전','水を張って稲などを栽培する田。','平野には水田が広がり、夏には一面が鮮やかな緑になる。','평야에는 논이 펼쳐져 여름이면 온통 선명한 초록빛이 된다.'),
('n1-3794','2027-02-01','雨天','うてん','우천; 비 오는 날씨','雨が降っている天候。','屋外イベントは雨天の場合、体育館で実施します。','야외 행사는 우천 시 체육관에서 실시합니다.'),
('n1-3795','2027-02-01','製鉄','せいてつ','제철; 철을 생산함','鉄鉱石などから鉄を取り出し、鉄鋼材料を製造すること。','この地域は古くから製鉄業を中心に発展してきた。','이 지역은 예로부터 제철업을 중심으로 발전해 왔다.'),
('n1-3796','2027-02-01','安静','あんせい','안정; 움직이지 않고 쉬는 상태','病気・けがなどの回復のため、心身を静かに保ち無理に動かないこと。','手術後はしばらく安静にして過ごすよう医師から言われた。','수술 후에는 한동안 안정을 취하라고 의사에게 들었다.'),
('n1-3797','2027-02-01','出血','しゅっけつ','출혈','血管が傷つくなどして、血液が血管の外へ流れ出ること。','出血が止まらない場合は、すぐに医療機関を受診してください。','출혈이 멈추지 않을 경우 즉시 의료기관을 방문해 주세요.'),
('n1-3798','2027-02-01','原形','げんけい','원형; 본래의 형태','変化・加工される前の、もとの形。','建物は何度も改修され、現在では原形をほとんど残していない。','건물은 여러 차례 개수되어 현재는 원형을 거의 남기지 않고 있다.'),
('n1-3799','2027-02-01','欲望','よくぼう','욕망; 강한 욕구','物・地位・快楽などを強く手に入れたい、満たしたいと思う気持ち。','目先の欲望だけで判断すると、長期的な利益を失うことがある。','눈앞의 욕망만으로 판단하면 장기적인 이익을 잃을 수 있다.'),
('n1-3800','2027-02-01','新築','しんちく','신축; 새로 지음; 새 건물','建物を新しく建てること。また、新しく建てられた建物。','駅の近くに新築のマンションが完成した。','역 근처에 신축 아파트가 완공됐다.');
INSERT INTO _n1_b9_words_0124(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3801','2027-02-02','案の定','あんのじょう','아니나 다를까; 예상대로','予想していたとおりの結果になったことを表す語。','準備不足のまま本番を迎えたため、案の定いくつものミスが起きた。','준비가 부족한 채 본番을 맞아서 아니나 다를까 여러 실수가 발생했다.'),
('n1-3802','2027-02-02','主任','しゅにん','주임; 담당 책임자','職場などで、特定の業務を中心となって担当する人。また、その役職。','判断に迷う場合は、まず担当主任に確認してから処理してください。','판단이 어려운 경우에는 먼저 담당 주임에게 확인한 뒤 처리해 주세요.'),
('n1-3803','2027-02-02','情熱','じょうねつ','열정; 정열','ある目標・活動・対象に対して強く熱心に向かう気持ち。','技術への情熱だけでなく、利用者の課題を理解する姿勢も開発者には必要だ。','기술에 대한 열정뿐 아니라 이용자의 과제를 이해하는 태도도 개발자에게 필요하다.'),
('n1-3804','2027-02-02','教員','きょういん','교원; 교사','学校・大学などの教育機関で、学生や生徒を教える職務に就く人。','少人数教育を維持するには、十分な数の教員を確保する必要がある。','소수 인원 교육을 유지하려면 충분한 수의 교원을 확보할 필요가 있다.'),
('n1-3805','2027-02-02','探検','たんけん','탐험; 미지의 곳을 조사함','未知の地域・場所などへ行き、実際に調べたり観察したりすること。','調査隊は未踏の洞窟を探検し、これまで知られていなかった生物を発見した。','조사대는 미답의 동굴을 탐험해 지금까지 알려지지 않았던 생물을 발견했다.'),
('n1-3806','2027-02-02','再会','さいかい','재회; 다시 만남','一度別れた人と、時間を置いて再び会うこと。','留学時代の友人と十年ぶりに再会し、昔の思い出を語り合った。','유학 시절 친구와 10년 만에 재회해 옛 추억을 이야기했다.'),
('n1-3807','2027-02-02','当選','とうせん','당선; 당첨','選挙で選ばれること。また、抽選・懸賞などで選ばれること。','新人候補が予想を上回る支持を集め、初めての選挙で当選した。','신인 후보가 예상보다 많은 지지를 얻어 첫 선거에서 당선되었다.'),
('n1-3808','2027-02-02','配布','はいふ','배포; 나누어 줌','資料・物品・冊子などを複数の人に配り、行き渡らせること。','会議資料は紙では配布せず、事前に共有フォルダへ保存することになった。','회의 자료는 종이로 배포하지 않고 사전에 공유 폴더에 저장하기로 했다.'),
('n1-3809','2027-02-02','気象','きしょう','기상; 대기 현상','気温・気圧・風・雨・雪・雲など、大気中で起こる自然現象。','近年は異常気象による豪雨や猛暑が各地で頻繁に報告されている。','최근에는 이상기상으로 인한 폭우와 폭염이 각지에서 자주 보고되고 있다.'),
('n1-3810','2027-02-02','預金','よきん','예금; 은행에 맡긴 돈','銀行などの金融機関に金銭を預けること。また、その預けた金銭。','急な出費に備えて、毎月一定額を普通預金に回している。','갑작스러운 지출에 대비해 매달 일정 금액을 보통예금에 넣고 있다.'),
('n1-3811','2027-02-02','伝言','でんごん','전언; 전달 메시지','その場にいない相手へ、別の人を通じて言葉・用件を伝えること。また、その内容。','担当者が不在だったので、折り返し連絡してほしいと伝言を残した。','담당자가 부재중이라 다시 연락해 달라는 전언을 남겼다.'),
('n1-3812','2027-02-02','隔週','かくしゅう','격주; 한 주 걸러','一週間おき。二週間に一度の間隔。','この会議は隔週で開かれる。','이 회의는 격주로 열린다.'),
('n1-3813','2027-02-02','真下','ました','바로 아래; 정하방','ある物の垂直方向のすぐ下。','窓の真下に車が止まっている。','창문 바로 아래에 차가 서 있다.'),
('n1-3814','2027-02-02','世辞','せじ','아첨; 빈말; 인사치레','相手の機嫌を取るために言う、実意のない褒め言葉。','お世辞ではなく、本当にすばらしいと思う。','빈말이 아니라 정말 훌륭하다고 생각한다.'),
('n1-3815','2027-02-02','気流','きりゅう','기류; 공기의 흐름','空気の流れ。','上昇気流が発生している。','상승 기류가 발생하고 있다.'),
('n1-3816','2027-02-02','来場','らいじょう','내장; 행사장에 옴; 방문','会場・催し物の場所へ来ること。','本日は多くの方にご来場いただいた。','오늘은 많은 분이 행사장을 찾아 주셨다.'),
('n1-3817','2027-02-02','見方','みかた','보는 법; 관점; 견해','物事を見る方法。また、物事をどの立場・観点から判断するかという考え方。','立場が変われば、同じ出来事でも見方は大きく変わる。','입장이 달라지면 같은 일도 보는 관점은 크게 달라진다.'),
('n1-3818','2027-02-02','点火','てんか','점화; 불을 붙임','燃料などに火をつけること。また、装置を作動させて燃焼を始めること。','ガスのにおいがするときは、絶対に点火してはいけない。','가스 냄새가 날 때는 절대로 점화해서는 안 된다.'),
('n1-3819','2027-02-02','私物','しぶつ','사물; 개인 소지품; 개인 물품','個人が所有している物。','会社の机に私物を置きすぎないようにしている。','회사 책상에 개인 물품을 너무 많이 두지 않으려고 한다.'),
('n1-3820','2027-02-02','特産','とくさん','특산; 특산품','ある地域で特に多く産出されること。また、その産物。','この町はみかんの特産地として知られている。','이 마을은 귤 특산지로 알려져 있다.'),
('n1-3821','2027-02-03','版画','はんが','판화','木・金属などの版に図柄を作り、紙などに刷った絵。','美術館で江戸時代の版画を見た。','미술관에서 에도 시대의 판화를 봤다.'),
('n1-3822','2027-02-03','字体','じたい','자체; 글자 모양; 서체','文字の形・書き方の型。','この漢字は古い字体で書かれている。','이 한자는 옛 글자체로 쓰여 있다.'),
('n1-3823','2027-02-03','姓名','せいめい','성명; 성과 이름','姓と名。氏名。','申込書に姓名を記入してください。','신청서에 성명을 기입해 주세요.'),
('n1-3824','2027-02-03','発芽','はつが','발아; 싹틈','種子から芽が出ること。','暖かくなると種が発芽し始める。','따뜻해지면 씨앗이 발아하기 시작한다.'),
('n1-3825','2027-02-03','考古学','こうこがく','고고학','遺跡・遺物などの物的資料から過去の人類の生活・文化を研究する学問。','彼女は大学で考古学を専攻し、古代の遺跡を研究している。','그녀는 대학에서 고고학을 전공하며 고대 유적을 연구하고 있다.'),
('n1-3826','2027-02-03','社宅','しゃたく','사택; 회사 제공 주택','会社などが従業員とその家族のために用意する住宅。','転勤後は会社の社宅に住むことになった。','전근 후에는 회사 사택에 살게 되었다.'),
('n1-3827','2027-02-03','休学','きゅうがく','휴학','学生の身分を保ったまま、一定期間学校での学業を休むこと。','留学の準備に集中するため、一年間休学した。','유학 준비에 집중하기 위해 1년간 휴학했다.'),
('n1-3828','2027-02-03','果たす','はたす','완수하다; 다하다','役割・責任・目的・約束などを最後まで実行して成し遂げる。','公共機関には、正確な情報を迅速に提供する役割を果たす責任がある。','공공기관에는 정확한 정보를 신속히 제공하는 역할을 다할 책임이 있다.'),
('n1-3829','2027-02-03','設ける','もうける','마련하다; 설치하다; 제정하다','施設・制度・機会・基準などを新しく作り、置く。','利用者の意見を聞くため、定期的な意見交換の場を設けることになった。','이용자의 의견을 듣기 위해 정기적인 의견 교환 자리를 마련하기로 했다.'),
('n1-3830','2027-02-03','逃れる','のがれる','벗어나다; 피하다; 면하다','危険・責任・不快な状況などから離れ、被害・負担を受けないようにする。','制度上の責任から逃れるために名義だけを変えることは認められない。','제도상의 책임을 피하기 위해 명의만 바꾸는 것은 인정되지 않는다.'),
('n1-3831','2027-02-03','受け入れる','うけいれる','받아들이다; 수용하다','人・意見・事実・文化などを拒まず認め、自分の側に取り入れる。','異なる意見を受け入れる姿勢が、建設的な議論には欠かせない。','다른 의견을 받아들이는 자세가 건설적인 논의에는 필수적이다.'),
('n1-3832','2027-02-03','満たす','みたす','채우다; 충족하다; 만족시키다','容器・場所などをいっぱいにする。また、条件・基準・要求などを十分に満足させる。','応募するには、三年以上の実務経験という条件を満たす必要がある。','지원하려면 3년 이상의 실무 경험이라는 조건을 충족해야 한다.'),
('n1-3833','2027-02-03','誤る','あやまる','잘못하다; 그르치다','判断・方法・理解などを間違える。','前提を誤ると、その後の分析も正しい結論にたどり着けない。','전제를 잘못 잡으면 이후 분석도 올바른 결론에 도달할 수 없다.'),
('n1-3834','2027-02-03','固める','かためる','굳히다; 다지다; 확정하다','柔らかいものを硬くする。また、方針・決意・基盤・体制などを確かなものにする。','関係者の意見を聞いたうえで、来年度の方針を固める。','관계자 의견을 들은 뒤 내년도 방침을 확정한다.'),
('n1-3835','2027-02-03','仕掛ける','しかける','장치를 설치하다; 일을 걸다; 시작하다','目的のために装置・罠などを設ける。また、相手に働きかけたり、ある行為を始めたりする。','攻撃を仕掛ける前に、相手の動きを慎重に分析した。','공격을 걸기 전에 상대의 움직임을 신중히 분석했다.'),
('n1-3836','2027-02-03','控える','ひかえる','삼가다; 줄이다; 앞두다','行動・量・発言などを抑える。また、予定された時期・出来事が近くに迫っている。','健康診断を翌日に控え、夜遅い食事を控えることにした。','건강검진을 다음 날 앞두고 늦은 밤 식사를 삼가기로 했다.'),
('n1-3837','2027-02-03','明かす','あかす','밝히다; 털어놓다; 밤을 새우다','秘密・原因・真相などを人に知らせて明らかにする。また、眠らず夜を過ごす。','調査委員会は事故の原因を明かすため、関係者への聞き取りを続けた。','조사위원회는 사고 원인을 밝히기 위해 관계자 면담을 계속했다.'),
('n1-3838','2027-02-03','仕上げる','しあげる','마무리하다; 완성하다','作業・作品・文章などに最後の手を加え、完成した状態にする。','報告書は内容を確認したうえで、今日中に仕上げる予定だ。','보고서는 내용을 확인한 뒤 오늘 안에 마무리할 예정이다.'),
('n1-3839','2027-02-03','滅びる','ほろびる','멸망하다; 사라지다; 파멸하다','国・組織・文化・生物などが衰えて完全になくなる。また、生活や事業などが破綻する。','環境の変化に適応できなければ、多くの生物種が滅びるおそれがある。','환경 변화에 적응하지 못하면 많은 생물종이 멸종할 우려가 있다.'),
('n1-3840','2027-02-03','素早い','すばやい','재빠르다; 신속하다; 민첩하다','動作・判断・対応などが非常に速く、無駄がない。','障害を最小限に抑えられたのは、担当者の素早い対応のおかげだ。','장애를 최소화할 수 있었던 것은 담당자의 신속한 대응 덕분이다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2027-01-21..2027-02-03' FROM _n1_b9_words_0124 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b9_map_0124(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b9_words_0124 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
