INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3568","prompt":"「慣らす」の読み方として最も適切なものを選びなさい。","options":["あやまる","とりのぞく","ほろびる","ならす"],"answer":"ならす","explanationKo":"「慣らす」는 「ならす」라고 읽는다. 뜻은 익숙하게 하다; 적응시키다; 길들이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3569","prompt":"「定める」の読み方として最も適切なものを選びなさい。","options":["あゆむ","しあげる","さだめる","はたす"],"answer":"さだめる","explanationKo":"「定める」는 「さだめる」라고 읽는다. 뜻은 정하다; 규정하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3570","prompt":"「催す」の読み方として最も適切なものを選びなさい。","options":["かためる","もよおす","さだまる","ならす"],"answer":"もよおす","explanationKo":"「催す」는 「もよおす」라고 읽는다. 뜻은 개최하다; 치르다; 느끼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3561","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工事の遅延によって生じた損害をどこまで（　）するか、契約内容を確認した。","options":["補償","背後","生死","定年"],"answer":"補償","explanationKo":"문맥상 「補償」가 가장 자연스럽다. 보상; 손실을 메움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3562","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n専用部品が届くまで、同じ性能を持つ別の部品で（　）することにした。","options":["富豪","味覚","衣装","代用"],"answer":"代用","explanationKo":"문맥상 「代用」가 가장 자연스럽다. 대용; 대신 사용함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3563","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n映画版では結末が（　）と大きく異なっている。","options":["退学","伝言","原作","化合"],"answer":"原作","explanationKo":"문맥상 「原作」가 가장 자연스럽다. 원작; 각색·번역 전의 본래 작품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3564","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の請求書を（　）して処理できるよう、経理システムを改修した。","options":["復活","一括","見方","復旧"],"answer":"一括","explanationKo":"문맥상 「一括」가 가장 자연스럽다. 일괄; 한꺼번에 묶어 처리함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3565","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n匿名だからといって、他人への（　）や中傷が許されるわけではない。","options":["悪口","屋敷","洪水","家計"],"answer":"悪口","explanationKo":"문맥상 「悪口」가 가장 자연스럽다. 악담; 욕설; 험담라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3566","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故を防ぐため、作業開始前に機器の安全（　）を必ず行う。","options":["送金","退職","配布","点検"],"answer":"点検","explanationKo":"문맥상 「点検」가 가장 자연스럽다. 점검; 하나하나 확인함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3567","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n後半に連続して（　）し、チームは逆転勝利を収めた。","options":["契機","屋敷","得点","探検"],"answer":"得点","explanationKo":"문맥상 「得点」가 가장 자연스럽다. 득점; 얻은 점수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3571","prompt":"「武器・体などをある姿勢に整える。また、店・家・拠点などを設ける。」という意味に最も近い語を選びなさい。","options":["栄える","構える","催す","仕掛ける"],"answer":"構える","explanationKo":"「構える」의 핵심 의미는 자세를 취하다; 마련하다; 차리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3572","prompt":"「目的地・結論・状態などに向かうよう人や物事を案内し、方向づける。」という意味に最も近い語を選びなさい。","options":["導く","仕上げる","逃れる","明かす"],"answer":"導く","explanationKo":"「導く」의 핵심 의미는 이끌다; 인도하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3573","prompt":"「歩いて進む。また比喩的に、人生・歴史・進路などを進んでいく。」という意味に最も近い語を選びなさい。","options":["果たす","導く","控える","歩む"],"answer":"歩む","explanationKo":"「歩む」의 핵심 의미는 걷다; 길을 나아가다; 과정을 밟다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3574","prompt":"「国・都市・産業・家系などが発展し、勢いが盛んになる。」という意味に最も近い語を選びなさい。","options":["催す","仕掛ける","栄える","定まる"],"answer":"栄える","explanationKo":"「栄える」의 핵심 의미는 번영하다; 번성하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3575","prompt":"「捕らえられた人・動物などを逃がす。また、機会・好機などをつかめず失う。」という意味に最も近い語を選びなさい。","options":["逃れる","逃す","歩む","仕上げる"],"answer":"逃す","explanationKo":"「逃す」의 핵심 의미는 놓치다; 기회를 잃다; 달아나게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','grammar',1,'〜と相まって','{"pattern":"〜と相まって","meaningKo":"〜와 어우러져; 〜와 맞물려","explanation":"〜と相まって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"技術の進歩が制度改革と相まって、業務の効率を高めた。","ko":"문맥에서 〜와 어우러져; 〜와 맞물려의 의미로 쓰였다."},{"ja":"強い風が乾燥と相まって、火災の被害を広げた。","ko":"이 문장도 〜와 어우러져; 〜와 맞물려의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','grammar',2,'〜に即して','{"pattern":"〜に即して","meaningKo":"〜에 입각하여; 〜에 맞추어","explanation":"〜に即して는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現場の実情に即して、運用規則を見直す必要がある。","ko":"문맥에서 〜에 입각하여; 〜에 맞추어의 의미로 쓰였다."},{"ja":"利用者の要望に即して、案内の内容を改めた。","ko":"이 문장도 〜에 입각하여; 〜에 맞추어의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n技術の進歩が制度改革（　）、業務の効率を高めた。","options":["〜と相まって","〜をよそに","〜ないではすまない","〜にもほどがある"],"answer":"〜と相まって","explanationKo":"문맥상 〜와 어우러져; 〜와 맞물려를 나타내는 「〜と相まって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n現場の実情（　）、運用規則を見直す必要がある。","options":["〜にかたくない","〜てやまない","〜に越したことはない","〜に即して"],"answer":"〜に即して","explanationKo":"문맥상 〜에 입각하여; 〜에 맞추어를 나타내는 「〜に即して」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今回の合意（　）、各分野で協力を進める。","options":["〜に足る","〜としたところで","〜を皮切りに","〜べからず"],"answer":"〜を皮切りに","explanationKo":"문맥상 〜을 시작으로를 나타내는 「〜を皮切りに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-21','reading',1,'補償を金額だけで考えない','{"passage":"被害を受けた人への補償制度を設計することには、生活の再建を支える手段を整えられることという意義がある。一方、金額だけを定めると失われた機会や地域との関係を見落とすことには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、被害の種類と回復に必要な時間も含めて支援を組み立てることが重要なのである。","questions":[{"prompt":"「補償を金額だけで考えない」について筆者が最も重視していることは何か。","options":["被害の種類と回復に必要な時間も含めて支援を組み立てること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"被害の種類と回復に必要な時間も含めて支援を組み立てること","explanationKo":"본문에서는 被害の種類と回復に必要な時間も含めて支援を組み立てること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["金額だけを定めると失われた機会や地域との関係を見落とすこと","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"金額だけを定めると失われた機会や地域との関係を見落とすこと","explanationKo":"주의할 점은 金額だけを定めると失われた機会や地域との関係を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["生活の再建を支える手段を整えられること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"生活の再建を支える手段を整えられること","explanationKo":"被害を受けた人への補償制度を設計すること에는 生活の再建を支える手段を整えられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3581","prompt":"「購読」の読み方として最も適切なものを選びなさい。","options":["こうどく","むごん","へいほう","しゅえい"],"answer":"こうどく","explanationKo":"「購読」는 「こうどく」라고 읽는다. 뜻은 구독; 돈을 내고 계속 받아 읽음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3582","prompt":"「敗戦」の読み方として最も適切なものを選びなさい。","options":["ほうさく","しぶつ","きょうちょう","はいせん"],"answer":"はいせん","explanationKo":"「敗戦」는 「はいせん」라고 읽는다. 뜻은 패전; 전쟁·전투에서 패함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3583","prompt":"「本体」の読み方として最も適切なものを選びなさい。","options":["へいき","さいぜん","ほんたい","いったい"],"answer":"ほんたい","explanationKo":"「本体」는 「ほんたい」라고 읽는다. 뜻은 본체; 중심이 되는 주요 부분이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3584","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雨に備え、自治体は（　）の水位を常時監視している。","options":["原文","河川","意地","肥料"],"answer":"河川","explanationKo":"문맥상 「河川」가 가장 자연스럽다. 하천; 크고 작은 강라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3585","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n資料の数値に誤りがあったため、（　）版を全員に再送した。","options":["訂正","破壊","再会","一帯"],"answer":"訂正","explanationKo":"문맥상 「訂正」가 가장 자연스럽다. 정정; 잘못된 내용을 바로잡음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3586","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n顧客の要望をすべて満たすことが、必ずしも（　）の解決策とは限らない。","options":["昆虫","真下","購読","究極"],"answer":"究極","explanationKo":"문맥상 「究極」가 가장 자연스럽다. 궁극; 끝까지 이른 최종·최고의 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3587","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの（　）が季節風を遮るため、東西で降水量に大きな差が生じる。","options":["確保","改良","山脈","点検"],"answer":"山脈","explanationKo":"문맥상 「山脈」가 가장 자연스럽다. 산맥라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3588","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部署間の連携が弱いと、担当者が問題を一人で抱えて（　）しやすい。","options":["紳士","孤立","高原","田園"],"answer":"孤立","explanationKo":"문맥상 「孤立」가 가장 자연스럽다. 고립; 고립됨라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3589","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n一度の障害対応を（　）に、運用手順全体を見直すことになった。","options":["契機","着席","夜行","著書"],"answer":"契機","explanationKo":"문맥상 「契機」가 가장 자연스럽다. 계기; 전환점이 되는 기회라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3590","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n停電した設備は深夜までに（　）し、翌朝から通常運転に戻った。","options":["社宅","勤務","処置","復旧"],"answer":"復旧","explanationKo":"문맥상 「復旧」가 가장 자연스럽다. 복구; 정상화라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3591","prompt":"「互いに立場を調整し、力を合わせて調和を保つこと。」という意味に最も近い語を選びなさい。","options":["観覧","出社","協調","優先"],"answer":"協調","explanationKo":"「協調」의 핵심 의미는 협조; 조화롭게 협력함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3592","prompt":"「ある場所を中心として、その周囲に広がる地域全体。」という意味に最も近い語を選びなさい。","options":["人目","一帯","定年","野外"],"answer":"一帯","explanationKo":"「一帯」의 핵심 의미는 일대; 주변 지역 전체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3593","prompt":"「特定の目的・用途のために使う道具や物品。」という意味に最も近い語を選びなさい。","options":["用品","衣装","雨天","考古学"],"answer":"用品","explanationKo":"「用品」의 핵심 의미는 용품; 특정 목적에 쓰는 물품이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3594","prompt":"「胸部・腹部など体内にある器官の総称。」という意味に最も近い語を選びなさい。","options":["版画","反射","昇進","内臓"],"answer":"内臓","explanationKo":"「内臓」의 핵심 의미는 내장; 몸속 장기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3595","prompt":"「光・音などが物体に当たって跳ね返ること。また、刺激に対し身体が無意識に反応すること。」という意味に最も近い語を選びなさい。","options":["故人","街道","反射","家計"],"answer":"反射","explanationKo":"「反射」의 핵심 의미는 반사; 반사 작용이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','grammar',1,'〜を皮切りに','{"pattern":"〜を皮切りに","meaningKo":"〜을 시작으로","explanation":"〜を皮切りに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"東京公演を皮切りに、全国十都市を巡回する。","ko":"문맥에서 〜을 시작으로의 의미로 쓰였다."},{"ja":"今回の合意を皮切りに、各分野で協力を進める。","ko":"이 문장도 〜을 시작으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','grammar',2,'〜を限りに','{"pattern":"〜を限りに","meaningKo":"〜을 끝으로","explanation":"〜を限りに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今月末を限りに、この窓口での受付を終了する。","ko":"문맥에서 〜을 끝으로의 의미로 쓰였다."},{"ja":"本日の公演を限りに、彼は舞台から退く。","ko":"이 문장도 〜을 끝으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n東京公演（　）、全国十都市を巡回する。","options":["〜べからず","〜に足る","〜としたところで","〜を皮切りに"],"answer":"〜を皮切りに","explanationKo":"문맥상 〜을 시작으로를 나타내는 「〜を皮切りに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今月末（　）、この窓口での受付を終了する。","options":["〜たりとも","〜ようによっては","〜を限りに","〜まじき"],"answer":"〜を限りに","explanationKo":"문맥상 〜을 끝으로를 나타내는 「〜を限りに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n周囲の批判（　）、彼女は改革を進めた。","options":["〜が最後","〜をものともせず","〜ずにはおかない","〜であれ"],"answer":"〜をものともせず","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をものともせず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-22','reading',1,'復旧と再発防止を両立する','{"passage":"停止した設備やサービスを元に戻すことには、生活や事業への影響を早く減らせることという意義がある。一方、速度だけを優先すると事故の原因を残したまま再開することには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、応急対応と原因分析の担当と期限を分けて管理することが重要なのである。","questions":[{"prompt":"「復旧と再発防止を両立する」について筆者が最も重視していることは何か。","options":["応急対応と原因分析の担当と期限を分けて管理すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"応急対応と原因分析の担当と期限を分けて管理すること","explanationKo":"본문에서는 応急対応と原因分析の担当と期限を分けて管理すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["速度だけを優先すると事故の原因を残したまま再開すること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"速度だけを優先すると事故の原因を残したまま再開すること","explanationKo":"주의할 점은 速度だけを優先すると事故の原因を残したまま再開すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["生活や事業への影響を早く減らせること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"生活や事業への影響を早く減らせること","explanationKo":"停止した設備やサービスを元に戻すこと에는 生活や事業への影響を早く減らせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3601","prompt":"「飼育」の読み方として最も適切なものを選びなさい。","options":["れんじゅう","しいく","しんちく","さんみゃく"],"answer":"しいく","explanationKo":"「飼育」는 「しいく」라고 읽는다. 뜻은 사육; 길러 기름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3602","prompt":"「宿命」の読み方として最も適切なものを選びなさい。","options":["しゅくめい","きょういん","とくてん","しじ"],"answer":"しゅくめい","explanationKo":"「宿命」는 「しゅくめい」라고 읽는다. 뜻은 숙명; 피하기 어려운 운명이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3603","prompt":"「斜面」の読み方として最も適切なものを選びなさい。","options":["してき","ちゅうどく","ほじゅう","しゃめん"],"answer":"しゃめん","explanationKo":"「斜面」는 「しゃめん」라고 읽는다. 뜻은 사면; 비탈면이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3604","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n退職後は小さな店を経営して（　）を立てている。","options":["出社","沸騰","生計","向き"],"answer":"生計","explanationKo":"문맥상 「生計」가 가장 자연스럽다. 생계; 생활을 유지하는 수단라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3605","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n将来の（　）探査に向けて、長期間の有人滞在を想定した実験が進められている。","options":["人質","火星","運送","原作"],"answer":"火星","explanationKo":"문맥상 「火星」가 가장 자연스럽다. 화성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3606","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部品不足が解消される時期はまだ分からず、生産再開の（　）は立っていない。","options":["見通し","斜面","本文","風習"],"answer":"見通し","explanationKo":"문맥상 「見通し」가 가장 자연스럽다. 전망; 예상; 내다봄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3607","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は本社（　）を経て、今年から海外支社で働くことになった。","options":["公演","入賞","家出","勤務"],"answer":"勤務","explanationKo":"문맥상 「勤務」가 가장 자연스럽다. 근무라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3608","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n犯人は（　）を解放する条件として、警察に複数の要求を突き付けた。","options":["好意","安静","人質","残高"],"answer":"人質","explanationKo":"문맥상 「人質」가 가장 자연스럽다. 인질; 볼모라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3609","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の証言を照合しなければ、事件の（　）にはたどり着けない。","options":["神秘","真実","良好","大幅"],"answer":"真実","explanationKo":"문맥상 「真実」가 가장 자연스럽다. 진실; 사실라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3610","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nシステム障害が発生したため、担当者を集めて（　）の対策会議を開いた。","options":["緊急","迅速","正常","健全"],"answer":"緊急","explanationKo":"문맥상 「緊急」가 가장 자연스럽다. 긴급라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3611","prompt":"「一方とは異なる側面や立場を示す語。文章では『他方、〜』の形で対照を示すことが多い。」という意味に最も近い語を選びなさい。","options":["壮大","台無し","気楽","他方"],"answer":"他方","explanationKo":"「他方」의 핵심 의미는 한편; 다른 한편으로는이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3612","prompt":"「周囲とのつながりがなく一人であること、またはそのように感じて寂しい状態。」という意味に最も近い語を選びなさい。","options":["有益","あっさり","孤独","真実"],"answer":"孤独","explanationKo":"「孤独」의 핵심 의미는 고독; 외로움이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3613","prompt":"「変化・増減・修正などの程度や範囲が非常に大きいこと。」という意味に最も近い語を選びなさい。","options":["とんだ","大幅","緊急","不調"],"answer":"大幅","explanationKo":"「大幅」의 핵심 의미는 대폭; 큰 폭이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3614","prompt":"「態度や姿が立派で自信に満ちているさま。また、人目を恐れず公然と行うさま。」という意味に最も近い語を選びなさい。","options":["堂々","強烈","貧乏","未定"],"answer":"堂々","explanationKo":"「堂々」의 핵심 의미는 당당하게; 위풍당당하게; 거리낌 없이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3615","prompt":"「異常や故障がなく、本来あるべき正しい状態であること。」という意味に最も近い語を選びなさい。","options":["堂々","良好","案の定","正常"],"answer":"正常","explanationKo":"「正常」의 핵심 의미는 정상; 이상 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','grammar',1,'〜をものともせず','{"pattern":"〜をものともせず","meaningKo":"〜을 아랑곳하지 않고","explanation":"〜をものともせず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"激しい雨をものともせず、救助隊は捜索を続けた。","ko":"문맥에서 〜을 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"周囲の批判をものともせず、彼女は改革を進めた。","ko":"이 문장도 〜을 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','grammar',2,'〜をよそに','{"pattern":"〜をよそに","meaningKo":"〜을 아랑곳하지 않고","explanation":"〜をよそに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"住民の不安をよそに、工事は予定どおり始まった。","ko":"문맥에서 〜을 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"周囲の期待をよそに、本人は冷静な態度を保った。","ko":"이 문장도 〜을 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n激しい雨（　）、救助隊は捜索を続けた。","options":["〜であれ","〜が最後","〜をものともせず","〜ずにはおかない"],"answer":"〜をものともせず","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をものともせず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n住民の不安（　）、工事は予定どおり始まった。","options":["〜そばから","〜をよそに","〜ずにはすまない","〜といえども"],"answer":"〜をよそに","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をよそに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の努力が報われた喜びは察する（　）。","options":["〜にかたくない","〜ないではすまない","〜ながらに","〜なり"],"answer":"〜にかたくない","explanationKo":"문맥상 충분히 〜할 수 있다를 나타내는 「〜にかたくない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-23','reading',1,'指標が行為を変える','{"passage":"成果を測るために数値目標を設けることには、進捗を共通の基準で確認できることという意義がある。一方、測りやすい数字だけを追うと本来の目的から行動がずれることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、指標が現場の判断に与える影響も定期的に検証することが重要なのである。","questions":[{"prompt":"「指標が行為を変える」について筆者が最も重視していることは何か。","options":["指標が現場の判断に与える影響も定期的に検証すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"指標が現場の判断に与える影響も定期的に検証すること","explanationKo":"본문에서는 指標が現場の判断に与える影響も定期的に検証すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["測りやすい数字だけを追うと本来の目的から行動がずれること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"測りやすい数字だけを追うと本来の目的から行動がずれること","explanationKo":"주의할 점은 測りやすい数字だけを追うと本来の目的から行動がずれること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["進捗を共通の基準で確認できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"進捗を共通の基準で確認できること","explanationKo":"成果を測るために数値目標を設けること에는 進捗を共通の基準で確認できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3621","prompt":"「支持」の読み方として最も適切なものを選びなさい。","options":["らっか","かんご","しじ","こうこがく"],"answer":"しじ","explanationKo":"「支持」는 「しじ」라고 읽는다. 뜻은 지지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3622","prompt":"「認識」の読み方として最も適切なものを選びなさい。","options":["ちゃくせき","にんしき","そうぞう","のりかえ"],"answer":"にんしき","explanationKo":"「認識」는 「にんしき」라고 읽는다. 뜻은 인식이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3623","prompt":"「監視」の読み方として最も適切なものを選びなさい。","options":["かんし","こうさく","へんとう","きゅうがく"],"answer":"かんし","explanationKo":"「監視」는 「かんし」라고 읽는다. 뜻은 감시; 주시이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3624","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n原材料価格の（　）が続けば、製品価格の見直しも避けられない。","options":["来場","宿命","少数","上昇"],"answer":"上昇","explanationKo":"문맥상 「上昇」가 가장 자연스럽다. 상승; 오름라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3625","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n計画の必要性を数字で示したことで、反対していた役員を（　）できた。","options":["上がり","外来","説得","素材"],"answer":"説得","explanationKo":"문맥상 「説得」가 가장 자연스럽다. 설득라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3626","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n来場者の安全を確保するため、入口ごとに警備員を（　）した。","options":["平方","配置","戦力","無言"],"answer":"配置","explanationKo":"문맥상 「配置」가 가장 자연스럽다. 배치; 배치 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3627","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n偶然の出会いがその後の人生を大きく変え、本人はそれを（　）だと感じた。","options":["運命","送金","退職","配布"],"answer":"運命","explanationKo":"문맥상 「運命」가 가장 자연스럽다. 운명; 운명적인 결과라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3628","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n防犯カメラの（　）を確認したところ、不審な人物が建物に入る様子が記録されていた。","options":["探検","契機","兵器","映像"],"answer":"映像","explanationKo":"문맥상 「映像」가 가장 자연스럽다. 영상; 화면에 비친 상라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3629","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の要望を受け、廃止されていた夜間便が来月から（　）する。","options":["放射","排水","復活","支持"],"answer":"復活","explanationKo":"문맥상 「復活」가 가장 자연스럽다. 부활; 재개; 회복라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3630","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n博物館では、発掘された資料を年代順に（　）している。","options":["再会","展示","保育","破壊"],"answer":"展示","explanationKo":"문맥상 「展示」가 가장 자연스럽다. 전시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3631","prompt":"「職場で現在より高い役職や地位に上がること。」という意味に最も近い語を選びなさい。","options":["昇進","出血","究極","部門"],"answer":"昇進","explanationKo":"「昇進」의 핵심 의미는 승진이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3632","prompt":"「それまで存在しなかった新しいものや価値を作り出すこと。」という意味に最も近い語を選びなさい。","options":["行為","脚本","陶器","創造"],"answer":"創造","explanationKo":"「創造」의 핵심 의미는 창조; 창출이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3633","prompt":"「組織や活動の全体を、役割や分野によって分けた一つの部分。」という意味に最も近い語を選びなさい。","options":["処置","推理","部門","勤務"],"answer":"部門","explanationKo":"「部門」의 핵심 의미는 부문; 부서이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3634","prompt":"「他のものより先に扱ったり、重要なものとして取り扱ったりすること。」という意味に最も近い語を選びなさい。","options":["主任","優先","当人","手数"],"answer":"優先","explanationKo":"「優先」의 핵심 의미는 우선; 우선시함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3635","prompt":"「同じ仲間に属する人々をまとめていう口語的な表現。文脈によっては軽い親しみや軽蔑を含む。」という意味に最も近い語を選びなさい。","options":["連中","返答","休学","火星"],"answer":"連中","explanationKo":"「連中」의 핵심 의미는 무리; 사람들; 녀석들이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','grammar',1,'〜にかたくない','{"pattern":"〜にかたくない","meaningKo":"충분히 〜할 수 있다","explanation":"〜にかたくない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"突然の閉鎖に利用者が困惑したことは想像にかたくない。","ko":"문맥에서 충분히 〜할 수 있다의 의미로 쓰였다."},{"ja":"長年の努力が報われた喜びは察するにかたくない。","ko":"이 문장도 충분히 〜할 수 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','grammar',2,'〜べからず','{"pattern":"〜べからず","meaningKo":"〜해서는 안 된다","explanation":"〜べからず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"許可なく資料を持ち出すべからず。","ko":"문맥에서 〜해서는 안 된다의 의미로 쓰였다."},{"ja":"初心忘るべからずという言葉を胸に刻んだ。","ko":"이 문장도 〜해서는 안 된다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n突然の閉鎖に利用者が困惑したことは想像（　）。","options":["〜なり","〜にかたくない","〜ないではすまない","〜ながらに"],"answer":"〜にかたくない","explanationKo":"문맥상 충분히 〜할 수 있다를 나타내는 「〜にかたくない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n許可なく資料を持ち出す（　）。","options":["〜べからず","〜てやまない","〜にもまして","〜や否や"],"answer":"〜べからず","explanationKo":"문맥상 〜해서는 안 된다를 나타내는 「〜べからず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n弱い立場の人を侮るのは、許す（　）態度である。","options":["〜に足る","〜にもほどがある","〜ようが〜まいが","〜まじき"],"answer":"〜まじき","explanationKo":"문맥상 〜에게 있을 수 없는; 〜해서는 안 될를 나타내는 「〜まじき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-24','reading',1,'少数意見を意思決定に残す','{"passage":"議論を経て組織の方針を決めることには、多くの人が納得する方向を選びやすくなることという意義がある。一方、多数決の結果だけでは反対意見が示した危険を失うことには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、採用しなかった意見とその理由も記録して見直せるようにすることが重要なのである。","questions":[{"prompt":"「少数意見を意思決定に残す」について筆者が最も重視していることは何か。","options":["採用しなかった意見とその理由も記録して見直せるようにすること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"採用しなかった意見とその理由も記録して見直せるようにすること","explanationKo":"본문에서는 採用しなかった意見とその理由も記録して見直せるようにすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["多数決の結果だけでは反対意見が示した危険を失うこと","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"多数決の結果だけでは反対意見が示した危険を失うこと","explanationKo":"주의할 점은 多数決の結果だけでは反対意見が示した危険を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["多くの人が納得する方向を選びやすくなること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"多くの人が納得する方向を選びやすくなること","explanationKo":"議論を経て組織の方針を決めること에는 多くの人が納得する方向を選びやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3641","prompt":"「素材」の読み方として最も適切なものを選びなさい。","options":["こりつ","はいち","けっせい","そざい"],"answer":"そざい","explanationKo":"「素材」는 「そざい」라고 읽는다. 뜻은 소재; 재료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3642","prompt":"「惑星」の読み方として最も適切なものを選びなさい。","options":["はいすい","そうしょく","わくせい","じゅうじつ"],"answer":"わくせい","explanationKo":"「惑星」는 「わくせい」라고 읽는다. 뜻은 행성이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3643","prompt":"「背後」の読み方として最も適切なものを選びなさい。","options":["いったい","はいご","はかい","さいかい"],"answer":"はいご","explanationKo":"「背後」는 「はいご」라고 읽는다. 뜻은 뒤; 배후; 배경이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3644","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の意見であっても、合理的な根拠があれば十分に検討すべきだ。","options":["少数","究極","部門","上位"],"answer":"少数","explanationKo":"문맥상 「少数」가 가장 자연스럽다. 소수; 적은 수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3645","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ理念を持つ（　）と出会ったことが、活動を続ける大きな支えになった。","options":["幹部","交互","体格","同志"],"answer":"同志","explanationKo":"문맥상 「同志」가 가장 자연스럽다. 동지; 뜻을 같이하는 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3646","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nけが人には現場で応急（　）を行った後、すぐに病院へ搬送した。","options":["新築","山脈","処置","着陸"],"answer":"処置","explanationKo":"문맥상 「処置」가 가장 자연스럽다. 처치; 조치; 처리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3647","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n加熱が不十分な食品を食べると、食（　）を起こす危険がある。","options":["幹部","中毒","本体","運命"],"answer":"中毒","explanationKo":"문맥상 「中毒」가 가장 자연스럽다. 중독; 중독 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3648","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多くの地方自治体が、人口減少と財政難という二つの課題に（　）している。","options":["直面","大金","原油","地主"],"answer":"直面","explanationKo":"문맥상 「直面」가 가장 자연스럽다. 직면; 맞닥뜨림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3649","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の意見をもとに製品を（　）し、操作性と耐久性を高めた。","options":["衣料","時差","暴風","改良"],"answer":"改良","explanationKo":"문맥상 「改良」가 가장 자연스럽다. 개량; 개선라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3650","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）数の減少が続き、地域の学校再編が大きな課題になっている。","options":["原形","補償","出生","幽霊"],"answer":"出生","explanationKo":"문맥상 「出生」가 가장 자연스럽다. 출생; 태어남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3651","prompt":"「中心から周囲へ向かって、光・熱・粒子・エネルギーなどを出すこと。」という意味に最も近い語を選びなさい。","options":["優先","放射","姓名","出動"],"answer":"放射","explanationKo":"「放射」의 핵심 의미는 방사; 방출이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3652","prompt":"「内容が十分に備わり、質的にも満たされていること。また、その状態にすること。」という意味に最も近い語を選びなさい。","options":["充実","展示","公演","入賞"],"answer":"充実","explanationKo":"「充実」의 핵심 의미는 충실; 내실; 알참이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3653","prompt":"「文書・手紙・記事・書籍などで、見出しや注記ではなく中心となる文章部分。」という意味に最も近い語を選びなさい。","options":["外来","残高","好意","本文"],"answer":"本文","explanationKo":"「本文」의 핵심 의미는 본문이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3654","prompt":"「物事の一つの側面。また、ある範囲全体に広がっている状態を表すこともある。」という意味に最も近い語を選びなさい。","options":["守衛","字体","一面","平方"],"answer":"一面","explanationKo":"「一面」의 핵심 의미는 일면; 한 측면; 온통이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3655","prompt":"「船で海や大きな水域を航行すること。また、その旅。」という意味に最も近い語を選びなさい。","options":["富豪","航海","死刑","向き"],"answer":"航海","explanationKo":"「航海」의 핵심 의미는 항해이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','grammar',1,'〜まじき','{"pattern":"〜まじき","meaningKo":"〜에게 있을 수 없는; 〜해서는 안 될","explanation":"〜まじき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事実を隠すとは、責任者にあるまじき行為だ。","ko":"문맥에서 〜에게 있을 수 없는; 〜해서는 안 될의 의미로 쓰였다."},{"ja":"弱い立場の人を侮るのは、許すまじき態度である。","ko":"이 문장도 〜에게 있을 수 없는; 〜해서는 안 될의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','grammar',2,'〜ずにはおかない','{"pattern":"〜ずにはおかない","meaningKo":"반드시 〜하게 만들다","explanation":"〜ずにはおかない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この作品は見る者を感動させずにはおかない。","ko":"문맥에서 반드시 〜하게 만들다의 의미로 쓰였다."},{"ja":"新たな証拠は、従来の解釈を変えずにはおかないだろう。","ko":"이 문장도 반드시 〜하게 만들다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事実を隠すとは、責任者にある（　）行為だ。","options":["〜まじき","〜に足る","〜にもほどがある","〜ようが〜まいが"],"answer":"〜まじき","explanationKo":"문맥상 〜에게 있을 수 없는; 〜해서는 안 될를 나타내는 「〜まじき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの作品は見る者を感動させ（　）。","options":["〜たりとも","〜に越したことはない","〜と相まって","〜ずにはおかない"],"answer":"〜ずにはおかない","explanationKo":"문맥상 반드시 〜하게 만들다를 나타내는 「〜ずにはおかない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n設備を壊した以上、弁償せ（　）。","options":["〜としたところで","〜に即して","〜ずにはすまない","〜であれ"],"answer":"〜ずにはすまない","explanationKo":"문맥상 〜하지 않고는 끝나지 않는다를 나타내는 「〜ずにはすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-25','reading',1,'感染対策の負担を配分する','{"passage":"感染の拡大を防ぐために行動を制限することには、社会全体の健康被害を抑えられることという意義がある。一方、一律の制限では職種や生活条件によって負担が偏ることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、効果と負担を集団ごとに調べて必要な支援を組み合わせることが重要なのである。","questions":[{"prompt":"「感染対策の負担を配分する」について筆者が最も重視していることは何か。","options":["効果と負担を集団ごとに調べて必要な支援を組み合わせること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"効果と負担を集団ごとに調べて必要な支援を組み合わせること","explanationKo":"본문에서는 効果と負担を集団ごとに調べて必要な支援を組み合わせること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["一律の制限では職種や生活条件によって負担が偏ること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"一律の制限では職種や生活条件によって負担が偏ること","explanationKo":"주의할 점은 一律の制限では職種や生活条件によって負担が偏ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["社会全体の健康被害を抑えられること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"社会全体の健康被害を抑えられること","explanationKo":"感染の拡大を防ぐために行動を制限すること에는 社会全体の健康被害を抑えられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3661","prompt":"「類似」の読み方として最も適切なものを選びなさい。","options":["るいじ","ぼきん","しゅぎょう","たんけん"],"answer":"るいじ","explanationKo":"「類似」는 「るいじ」라고 읽는다. 뜻은 유사; 비슷함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3662","prompt":"「脚本」の読み方として最も適切なものを選びなさい。","options":["でんえん","しんし","きしょう","きゃくほん"],"answer":"きゃくほん","explanationKo":"「脚本」는 「きゃくほん」라고 읽는다. 뜻은 각본; 대본; 시나리오이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3663","prompt":"「幹部」の読み方として最も適切なものを選びなさい。","options":["いっかつ","たいおう","かんぶ","しゅにん"],"answer":"かんぶ","explanationKo":"「幹部」는 「かんぶ」라고 읽는다. 뜻은 간부; 핵심 관리자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3664","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n連休中は（　）が増えるため、鉄道会社は臨時列車を運行する。","options":["同感","旅客","飼育","看護"],"answer":"旅客","explanationKo":"문맥상 「旅客」가 가장 자연스럽다. 여객; 승객라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3665","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）を張って一人で抱え込まず、難しいときは周囲に助けを求めたほうがいい。","options":["意地","乗り換え","入賞","家出"],"answer":"意地","explanationKo":"문맥상 「意地」가 가장 자연스럽다. 고집; 오기; 자존심라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3666","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n検索結果の（　）に表示されるからといって、必ずしも内容が正確とは限らない。","options":["装備","発芽","生計","上位"],"answer":"上位","explanationKo":"문맥상 「上位」가 가장 자연스럽다. 상위; 높은 순위라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3667","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n海外（　）の成功を受け、同じ作品を国内でも再演することが決まった。","options":["昇進","乗り換え","公演","反射"],"answer":"公演","explanationKo":"문맥상 「公演」가 가장 자연스럽다. 공연; 공개 상연라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3668","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n集中豪雨による（　）で道路が冠水し、多くの住民が避難した。","options":["堤防","洪水","組み合わせ","近郊"],"answer":"洪水","explanationKo":"문맥상 「洪水」가 가장 자연스럽다. 홍수; 범람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3669","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n完全な解決が難しくても、今できる（　）の方法を選ぶしかない。","options":["最善","故人","街道","水田"],"answer":"最善","explanationKo":"문맥상 「最善」가 가장 자연스럽다. 최선; 가장 좋은 방법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3670","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの駅で地下鉄に（　）れば、目的地まで最短で行ける。","options":["内臓","素材","上がり","乗り換え"],"answer":"乗り換え","explanationKo":"문맥상 「乗り換え」가 가장 자연스럽다. 환승; 갈아타기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3671","prompt":"「財産・収入が少なく、生活に十分な余裕がないこと。」という意味に最も近い語を選びなさい。","options":["台無し","真実","貧乏","健全"],"answer":"貧乏","explanationKo":"「貧乏」의 핵심 의미는 가난; 빈곤함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3672","prompt":"「味・性格などがしつこくなく淡泊なさま。また、意外なほど簡単に物事が進むさま。」という意味に最も近い語を選びなさい。","options":["神秘","あっさり","良好","他方"],"answer":"あっさり","explanationKo":"「あっさり」의 핵심 의미는 담백하게; 쉽게; 미련 없이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3673","prompt":"「展示・公演・競技などを見て楽しむこと。」という意味に最も近い語を選びなさい。","options":["観覧","真珠","世辞","敗戦"],"answer":"観覧","explanationKo":"「観覧」의 핵심 의미는 관람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3674","prompt":"「様子・行動・事情などが怪しく、疑わしいと感じられること。」という意味に最も近い語を選びなさい。","options":["未定","無難","堂々","不審"],"answer":"不審","explanationKo":"「不審」의 핵심 의미는 수상함; 의심스러움; 의혹이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3675","prompt":"「向いている方向。また、人や用途に適していることを表す。」という意味に最も近い語を選びなさい。","options":["創造","改良","向き","勤務"],"answer":"向き","explanationKo":"「向き」의 핵심 의미는 방향; 적합함; ~용이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','grammar',1,'〜ずにはすまない','{"pattern":"〜ずにはすまない","meaningKo":"〜하지 않고는 끝나지 않는다","explanation":"〜ずにはすまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"重大な誤りには、責任者が説明せずにはすまない。","ko":"문맥에서 〜하지 않고는 끝나지 않는다의 의미로 쓰였다."},{"ja":"設備を壊した以上、弁償せずにはすまない。","ko":"이 문장도 〜하지 않고는 끝나지 않는다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','grammar',2,'〜ないではすまない','{"pattern":"〜ないではすまない","meaningKo":"〜하지 않고는 넘어갈 수 없다","explanation":"〜ないではすまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"これほどの遅延なら、原因を公表しないではすまない。","ko":"문맥에서 〜하지 않고는 넘어갈 수 없다의 의미로 쓰였다."},{"ja":"約束を破った以上、謝らないではすまない。","ko":"이 문장도 〜하지 않고는 넘어갈 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n重大な誤りには、責任者が説明せ（　）。","options":["〜であれ","〜としたところで","〜に即して","〜ずにはすまない"],"answer":"〜ずにはすまない","explanationKo":"문맥상 〜하지 않고는 끝나지 않는다를 나타내는 「〜ずにはすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこれほどの遅延なら、原因を公表し（　）。","options":["〜ようによっては","〜を皮切りに","〜ないではすまない","〜といえども"],"answer":"〜ないではすまない","explanationKo":"문맥상 〜하지 않고는 넘어갈 수 없다를 나타내는 「〜ないではすまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n若い研究者の活躍を期待し（　）。","options":["〜を限りに","〜てやまない","〜ながらに","〜が最後"],"answer":"〜てやまない","explanationKo":"문맥상 진심으로 계속 〜하다를 나타내는 「〜てやまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-26','reading',1,'文化財の修復で新しさを隠さない','{"passage":"傷んだ建物や作品を修復して保存することには、将来の世代が文化的価値に触れられることという意義がある。一方、新しい材料を古い部分と見分けられなくすると来歴を誤解させることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、修復箇所と使用材料を記録し識別可能性を保つことが重要なのである。","questions":[{"prompt":"「文化財の修復で新しさを隠さない」について筆者が最も重視していることは何か。","options":["修復箇所と使用材料を記録し識別可能性を保つこと","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"修復箇所と使用材料を記録し識別可能性を保つこと","explanationKo":"본문에서는 修復箇所と使用材料を記録し識別可能性を保つこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["新しい材料を古い部分と見分けられなくすると来歴を誤解させること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"新しい材料を古い部分と見分けられなくすると来歴を誤解させること","explanationKo":"주의할 점은 新しい材料を古い部分と見分けられなくすると来歴を誤解させること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["将来の世代が文化的価値に触れられること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"将来の世代が文化的価値に触れられること","explanationKo":"傷んだ建物や作品を修復して保存すること에는 将来の世代が文化的価値に触れられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3681","prompt":"「同感」の読み方として最も適切なものを選びなさい。","options":["しゃたく","どうかん","こうい","あんせい"],"answer":"どうかん","explanationKo":"「同感」는 「どうかん」라고 읽는다. 뜻은 동감; 같은 생각이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
