INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3686","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nまだ（　）な点は多いが、経験を積みながら改善していきたい。","options":["未熟","孤独","気楽","貧乏"],"answer":"未熟","explanationKo":"문맥상 「未熟」가 가장 자연스럽다. 미숙함; 미성숙라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3687","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n残された記録から当時何が起きたのかを（　）するのが、この作品の面白さだ。","options":["立体","樹木","赤字","推理"],"answer":"推理","explanationKo":"문맥상 「推理」가 가장 자연스럽다. 추리; 추론라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3688","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害直後の数時間は、被災者の（　）を左右する重要な時間だ。","options":["破壊","再会","生死","保育"],"answer":"生死","explanationKo":"문맥상 「生死」가 가장 자연스럽다. 생사; 삶과 죽음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3689","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの装置は電力ではなく圧縮空気を（　）として作動する。","options":["部門","動力","出血","究極"],"answer":"動力","explanationKo":"문맥상 「動力」가 가장 자연스럽다. 동력; 기계를 움직이는 힘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3690","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n在庫が一定数を下回ると、自動的に商品を（　）する仕組みになっている。","options":["補充","対応","直面","同居"],"answer":"補充","explanationKo":"문맥상 「補充」가 가장 자연스럽다. 보충; 부족한 것을 채움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3691","prompt":"「昔の生物の遺体・痕跡などが地層中に残ったもの。」という意味に最も近い語を選びなさい。","options":["電線","結核","根気","化石"],"answer":"化石","explanationKo":"「化石」의 핵심 의미는 화석이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3692","prompt":"「寄付金・義援金などを広く呼びかけて集めること。」という意味に最も近い語を選びなさい。","options":["本体","運命","募金","沸騰"],"answer":"募金","explanationKo":"「募金」의 핵심 의미는 모금; 기부금을 모음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3693","prompt":"「高く険しい山々。また、山に関係する地域・活動。」という意味に最も近い語を選びなさい。","options":["指摘","山岳","欲望","代用"],"answer":"山岳","explanationKo":"「山岳」의 핵심 의미는 산악; 높고 험한 산들이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3694","prompt":"「ある地域・社会に昔から受け継がれている生活上の習慣・ならわし。」という意味に最も近い語を選びなさい。","options":["風習","落下","感染","向き"],"answer":"風習","explanationKo":"「風習」의 핵심 의미는 풍습; 오래된 생활 관습이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3695","prompt":"「地下から採掘されたままで、まだ精製されていない石油。」という意味に最も近い語を選びなさい。","options":["公演","朗読","運送","原油"],"answer":"原油","explanationKo":"「原油」의 핵심 의미는 원유이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','grammar',1,'〜てやまない','{"pattern":"〜てやまない","meaningKo":"진심으로 계속 〜하다","explanation":"〜てやまない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"被災地の一日も早い復旧を願ってやまない。","ko":"문맥에서 진심으로 계속 〜하다의 의미로 쓰였다."},{"ja":"若い研究者の活躍を期待してやまない。","ko":"이 문장도 진심으로 계속 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','grammar',2,'〜に足る','{"pattern":"〜に足る","meaningKo":"〜할 만하다","explanation":"〜に足る는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この調査は政策判断の根拠に足る資料である。","ko":"문맥에서 〜할 만하다의 의미로 쓰였다."},{"ja":"彼の行動は十分に信頼に足るものだ。","ko":"이 문장도 〜할 만하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n被災地の一日も早い復旧を願っ（　）。","options":["〜が最後","〜を限りに","〜てやまない","〜ながらに"],"answer":"〜てやまない","explanationKo":"문맥상 진심으로 계속 〜하다를 나타내는 「〜てやまない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの調査は政策判断の根拠（　）資料である。","options":["〜をものともせず","〜に足る","〜にもまして","〜そばから"],"answer":"〜に足る","explanationKo":"문맥상 〜할 만하다를 나타내는 「〜に足る」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n機密情報は一文字（　）外部に漏らせない。","options":["〜たりとも","〜にもほどがある","〜なり","〜をよそに"],"answer":"〜たりとも","explanationKo":"문맥상 단 〜라도를 나타내는 「〜たりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-27','reading',1,'自動化後の監視を設計する','{"passage":"定型的な判断をシステムに任せることには、大量の処理を速く一貫して行えることという意義がある。一方、運用後の誤りを人が確認しなければ偏りが繰り返されることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、異常を発見して停止し修正できる責任者と手順を置くことが重要なのである。","questions":[{"prompt":"「自動化後の監視を設計する」について筆者が最も重視していることは何か。","options":["異常を発見して停止し修正できる責任者と手順を置くこと","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"異常を発見して停止し修正できる責任者と手順を置くこと","explanationKo":"본문에서는 異常を発見して停止し修正できる責任者と手順を置くこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["運用後の誤りを人が確認しなければ偏りが繰り返されること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"運用後の誤りを人が確認しなければ偏りが繰り返されること","explanationKo":"주의할 점은 運用後の誤りを人が確認しなければ偏りが繰り返されること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["大量の処理を速く一貫して行えること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"大量の処理を速く一貫して行えること","explanationKo":"定型的な判断をシステムに任せること에는 大量の処理を速く一貫して行えること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3701","prompt":"「交互」の読み方として最も適切なものを選びなさい。","options":["しぶつ","ふっきゅう","こうご","ほうさく"],"answer":"こうご","explanationKo":"「交互」는 「こうご」라고 읽는다. 뜻은 교대로; 번갈아이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3702","prompt":"「送金」の読み方として最も適切なものを選びなさい。","options":["げんぶん","そうきん","じょうい","ひりょう"],"answer":"そうきん","explanationKo":"「送金」는 「そうきん」라고 읽는다. 뜻은 송금이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3703","prompt":"「立体」の読み方として最も適切なものを選びなさい。","options":["りったい","しゅっしょう","どうきょ","しゅうしゅう"],"answer":"りったい","explanationKo":"「立体」는 「りったい」라고 읽는다. 뜻은 입체; 입체물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3704","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n作物の種類に合わせて（　）の量を調整しなければならない。","options":["着陸","新築","山脈","肥料"],"answer":"肥料","explanationKo":"문맥상 「肥料」가 가장 자연스럽다. 비료; 거름라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3705","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n経験豊富な選手の復帰は、チームにとって大きな（　）になる。","options":["運命","幹部","戦力","本体"],"answer":"戦力","explanationKo":"문맥상 「戦力」가 가장 자연스럽다. 전력; 싸울 수 있는 능력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3706","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n物価の上昇が続き、（　）への負担が以前より大きくなっている。","options":["津波","家計","大金","電線"],"answer":"家計","explanationKo":"문맥상 「家計」가 가장 자연스럽다. 가계; 가정의 수입과 지출라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3707","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその（　）は私財を投じて、地域の教育施設を建設した。","options":["富豪","高原","田園","紳士"],"answer":"富豪","explanationKo":"문맥상 「富豪」가 가장 자연스럽다. 부호; 매우 큰 부자라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3708","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）植物の増加が地域の生態系に影響を及ぼしている。","options":["手数","主任","一括","外来"],"answer":"外来","explanationKo":"문맥상 「外来」가 가장 자연스럽다. 외래; 외부에서 들어옴라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3709","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n都心の家賃が高いため、（　）から通勤する人も多い。","options":["飼育","看護","近郊","社宅"],"answer":"近郊","explanationKo":"문맥상 「近郊」가 가장 자연스럽다. 근교; 도시 주변 지역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3710","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雨に備えて、道路の（　）設備を点検する作業が行われた。","options":["人目","排水","定年","野外"],"answer":"排水","explanationKo":"문맥상 「排水」가 가장 자연스럽다. 배수; 물을 빼냄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3711","prompt":"「二つ以上の元素・物質が化学的に結びつき、別の性質を持つ物質になること。」という意味に最も近い語を選びなさい。","options":["化合","衣装","雨天","考古学"],"answer":"化合","explanationKo":"「化合」의 핵심 의미는 화합; 화학적으로 결합함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3712","prompt":"「勤務先の規定などによって、退職することと定められている年齢。」という意味に最も近い語を選びなさい。","options":["伝言","情緒","背後","定年"],"answer":"定年","explanationKo":"「定年」의 핵심 의미는 정년이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3713","prompt":"「恒星・惑星・衛星など、宇宙空間に存在する物体。」という意味に最も近い語を選びなさい。","options":["上がり","外来","天体","死刑"],"answer":"天体","explanationKo":"「天体」의 핵심 의미는 천체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3714","prompt":"「衣服や、その材料となる布地などの総称。」という意味に最も近い語を選びなさい。","options":["街道","衣料","戦力","故人"],"answer":"衣料","explanationKo":"「衣料」의 핵심 의미는 의류; 의복 재료 및 옷이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3715","prompt":"「人が自然に持つ感情。特に、他人への思いやり・情け・温かい気持ち。」という意味に最も近い語を選びなさい。","options":["人情","赤字","既婚","特産"],"answer":"人情","explanationKo":"「人情」의 핵심 의미는 인정; 사람의 정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','grammar',1,'〜たりとも','{"pattern":"〜たりとも","meaningKo":"단 〜라도","explanation":"〜たりとも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"締め切りまで一分たりとも無駄にはできない。","ko":"문맥에서 단 〜라도의 의미로 쓰였다."},{"ja":"機密情報は一文字たりとも外部に漏らせない。","ko":"이 문장도 단 〜라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','grammar',2,'〜であれ','{"pattern":"〜であれ","meaningKo":"〜이든","explanation":"〜であれ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"どのような理由であれ、差別は認められない。","ko":"문맥에서 〜이든의 의미로 쓰였다."},{"ja":"小さな改善であれ、継続すれば大きな成果になる。","ko":"이 문장도 〜이든의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n締め切りまで一分（　）無駄にはできない。","options":["〜をよそに","〜たりとも","〜にもほどがある","〜なり"],"answer":"〜たりとも","explanationKo":"문맥상 단 〜라도를 나타내는 「〜たりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nどのような理由（　）、差別は認められない。","options":["〜であれ","〜に越したことはない","〜や否や","〜にかたくない"],"answer":"〜であれ","explanationKo":"문맥상 〜이든를 나타내는 「〜であれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n緊急時（　）、記録を残す必要がある。","options":["〜としたところで","〜ようが〜まいが","〜べからず","〜といえども"],"answer":"〜といえども","explanationKo":"문맥상 비록 〜라 하더라도를 나타내는 「〜といえども」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-28','reading',1,'予算の年度境界を越えて考える','{"passage":"限られた資金を年度ごとに配分することには、支出の責任と進捗を定期的に確認できることという意義がある。一方、短期の消化を優先すると維持費や将来の効果を軽視することには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、事業の全期間に必要な費用と成果を合わせて評価することが重要なのである。","questions":[{"prompt":"「予算の年度境界を越えて考える」について筆者が最も重視していることは何か。","options":["事業の全期間に必要な費用と成果を合わせて評価すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"事業の全期間に必要な費用と成果を合わせて評価すること","explanationKo":"본문에서는 事業の全期間に必要な費用と成果を合わせて評価すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["短期の消化を優先すると維持費や将来の効果を軽視すること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"短期の消化を優先すると維持費や将来の効果を軽視すること","explanationKo":"주의할 점은 短期の消化を優先すると維持費や将来の効果を軽視すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["支出の責任と進捗を定期的に確認できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"支出の責任と進捗を定期的に確認できること","explanationKo":"限られた資金を年度ごとに配分すること에는 支出の責任と進捗を定期的に確認できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3721","prompt":"「静止」の読み方として最も適切なものを選びなさい。","options":["してき","ちゅうどく","ぼきん","せいし"],"answer":"せいし","explanationKo":"「静止」는 「せいし」라고 읽는다. 뜻은 정지; 움직이지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3722","prompt":"「体格」の読み方として最も適切なものを選びなさい。","options":["こうげん","かんせい","たいかく","ふうしゅう"],"answer":"たいかく","explanationKo":"「体格」는 「たいかく」라고 읽는다. 뜻은 체격; 몸집이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3723","prompt":"「樹木」の読み方として最も適切なものを選びなさい。","options":["じょうねつ","じゅもく","じさ","ぼうふう"],"answer":"じゅもく","explanationKo":"「樹木」는 「じゅもく」라고 읽는다. 뜻은 수목; 나무이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3724","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n翻訳だけで意味が曖昧な場合は、（　）を確認したほうがよい。","options":["原文","原形","補償","勤務"],"answer":"原文","explanationKo":"문맥상 「原文」가 가장 자연스럽다. 원문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3725","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は質問に答えず、（　）のまま部屋を出ていった。","options":["出動","優先","観覧","無言"],"answer":"無言","explanationKo":"문맥상 「無言」가 가장 자연스럽다. 무언; 말이 없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3726","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n式典では（　）の功績を振り返り、黙とうがささげられた。","options":["耕作","返答","故人","類似"],"answer":"故人","explanationKo":"문맥상 「故人」가 가장 자연스럽다. 고인; 세상을 떠난 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3727","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n体調によって（　）が変わり、普段と違う味に感じることもある。","options":["宿命","味覚","脱出","来場"],"answer":"味覚","explanationKo":"문맥상 「味覚」가 가장 자연스럽다. 미각라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3728","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n振り込みの前に口座の（　）を確認した。","options":["残高","内臓","素材","組み合わせ"],"answer":"残高","explanationKo":"문맥상 「残高」가 가장 자연스럽다. 잔고; 남은 금액라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3729","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雨に備えて、老朽化した（　）の補強工事が進められている。","options":["洪水","家計","故人","堤防"],"answer":"堤防","explanationKo":"문맥상 「堤防」가 가장 자연스럽다. 제방; 둑라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3730","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n雨天の場合、（　）イベントは体育館で実施される。","options":["徒歩","始発","野外","樹木"],"answer":"野外","explanationKo":"문맥상 「野外」가 가장 자연스럽다. 야외; 옥외라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3731","prompt":"「その事柄に直接関係している本人。」という意味に最も近い語を選びなさい。","options":["孤立","当人","短歌","見方"],"answer":"当人","explanationKo":"「当人」의 핵심 의미는 당사자 본인; 바로 그 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3732","prompt":"「地域・国の標準時の差。また、出来事の発生時刻などの時間的なずれ。」という意味に最も近い語を選びなさい。","options":["時差","購読","監視","充実"],"answer":"時差","explanationKo":"「時差」의 핵심 의미는 시차; 시간 차이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3733","prompt":"「同じ会社・組織の中で、勤務地が別の場所へ変わること。」という意味に最も近い語を選びなさい。","options":["津波","兵士","仏像","転勤"],"answer":"転勤","explanationKo":"「転勤」의 핵심 의미는 전근; 근무지 이동이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3734","prompt":"「植物・動物などが成長し、育つこと。」という意味に最も近い語を選びなさい。","options":["気象","複合","生育","紳士"],"answer":"生育","explanationKo":"「生育」의 핵심 의미는 생육; 자라남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3735","prompt":"「田畑を耕し、作物を育てること。」という意味に最も近い語を選びなさい。","options":["直面","耕作","一括","対応"],"answer":"耕作","explanationKo":"「耕作」의 핵심 의미는 경작이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','grammar',1,'〜といえども','{"pattern":"〜といえども","meaningKo":"비록 〜라 하더라도","explanation":"〜といえども는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"専門家といえども、判断を誤ることはある。","ko":"문맥에서 비록 〜라 하더라도의 의미로 쓰였다."},{"ja":"緊急時といえども、記録を残す必要がある。","ko":"이 문장도 비록 〜라 하더라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','grammar',2,'〜ながらに','{"pattern":"〜ながらに","meaningKo":"〜인 채로; 〜하면서","explanation":"〜ながらに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は生まれながらに優れた感覚を備えていた。","ko":"문맥에서 〜인 채로; 〜하면서의 의미로 쓰였다."},{"ja":"その建物は昔ながらに木材で造られている。","ko":"이 문장도 〜인 채로; 〜하면서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、判断を誤ることはある。","options":["〜といえども","〜としたところで","〜ようが〜まいが","〜べからず"],"answer":"〜といえども","explanationKo":"문맥상 비록 〜라 하더라도를 나타내는 「〜といえども」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は生まれ（　）優れた感覚を備えていた。","options":["〜ようによっては","〜と相まって","〜まじき","〜ながらに"],"answer":"〜ながらに","explanationKo":"문맥상 〜인 채로; 〜하면서를 나타내는 「〜ながらに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n完成の喜び（　）、支援への感謝を強く感じた。","options":["〜に即して","〜ずにはおかない","〜にもまして","〜が最後"],"answer":"〜にもまして","explanationKo":"문맥상 〜보다도 더를 나타내는 「〜にもまして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-29','reading',1,'匿名化にも限界がある','{"passage":"個人情報から氏名などを除いてデータを共有することには、プライバシーを守りながら分析に活用できることという意義がある。一方、複数の情報を組み合わせると個人を再び特定できる場合があることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、利用目的と提供範囲に応じて再識別の危険を評価することが重要なのである。","questions":[{"prompt":"「匿名化にも限界がある」について筆者が最も重視していることは何か。","options":["利用目的と提供範囲に応じて再識別の危険を評価すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"利用目的と提供範囲に応じて再識別の危険を評価すること","explanationKo":"본문에서는 利用目的と提供範囲に応じて再識別の危険を評価すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["複数の情報を組み合わせると個人を再び特定できる場合があること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"複数の情報を組み合わせると個人を再び特定できる場合があること","explanationKo":"주의할 점은 複数の情報を組み合わせると個人を再び特定できる場合があること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["プライバシーを守りながら分析に活用できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"プライバシーを守りながら分析に活用できること","explanationKo":"個人情報から氏名などを除いてデータを共有すること에는 プライバシーを守りながら分析に活用できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3741","prompt":"「出社」の読み方として最も適切なものを選びなさい。","options":["しゅっしゃ","きんこう","ていぼう","ゆうれい"],"answer":"しゅっしゃ","explanationKo":"「出社」는 「しゅっしゃ」라고 읽는다. 뜻은 출사; 회사에 출근함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3742","prompt":"「歓声」の読み方として最も適切なものを選びなさい。","options":["てんきん","しんどう","てんか","かんせい"],"answer":"かんせい","explanationKo":"「歓声」는 「かんせい」라고 읽는다. 뜻은 환호성; 기쁨의 함성이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3743","prompt":"「根気」の読み方として最も適切なものを選びなさい。","options":["しきさい","わくせい","こんき","よきん"],"answer":"こんき","explanationKo":"「根気」는 「こんき」라고 읽는다. 뜻은 끈기; 인내력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3744","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明会は（　）百名まで参加できる。","options":["転勤","先着","説得","告白"],"answer":"先着","explanationKo":"문맥상 「先着」가 가장 자연스럽다. 선착; 먼저 도착함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3745","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n情報漏えいが疑われる場合は、被害を広げないため（　）な対応が必要だ。","options":["迅速","無意味","壮大","孤独"],"answer":"迅速","explanationKo":"문맥상 「迅速」가 가장 자연스럽다. 신속; 매우 빠름라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3746","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n宇宙開発という（　）な計画を実現するには、長期的な資金と人材が必要だ。","options":["案の定","神秘","大幅","壮大"],"answer":"壮大","explanationKo":"문맥상 「壮大」가 가장 자연스럽다. 장대; 웅대; 규모가 매우 큼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3747","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n深海にはまだ観測されていない生物が多く、生命の（　）を感じさせる。","options":["強烈","正常","神秘","隔週"],"answer":"神秘","explanationKo":"문맥상 「神秘」가 가장 자연스럽다. 신비; 불가사의함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3748","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n初めて会ったときの（　）な印象は、数年たった今でもよく覚えている。","options":["台無し","強烈","素早い","健全"],"answer":"強烈","explanationKo":"문맥상 「強烈」가 가장 자연스럽다. 강렬함; 매우 강함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3749","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n市場を（　）に発展させるには、公正な競争を守る仕組みが必要だ。","options":["健全","孤独","気楽","貧乏"],"answer":"健全","explanationKo":"문맥상 「健全」가 가장 자연스럽다. 건전함; 건강하고 정상적임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3750","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n結果を気にしすぎず、もう少し（　）に挑戦してみてもいいと思う。","options":["大幅","盛大","不審","気楽"],"answer":"気楽","explanationKo":"문맥상 「気楽」가 가장 자연스럽다. 마음 편함; 부담이 없음; 느긋함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3751","prompt":"「行事・催しなどの規模が大きく、にぎやかで立派なさま。」という意味に最も近い語を選びなさい。","options":["未定","無能","盛大","正常"],"answer":"盛大","explanationKo":"「盛大」의 핵심 의미는 성대함; 규모가 크고 화려함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3752","prompt":"「予定・方法・担当などがまだ決まっていないこと。」という意味に最も近い語を選びなさい。","options":["無難","未定","台無し","真実"],"answer":"未定","explanationKo":"「未定」의 핵심 의미는 미정; 아직 정해지지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3753","prompt":"「意味・価値・効果などがないこと。」という意味に最も近い語を選びなさい。","options":["無意味","大幅","神秘","貧乏"],"answer":"無意味","explanationKo":"「無意味」의 핵심 의미는 무의미함; 의미 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3754","prompt":"「物を身に付けて持ち歩くこと。また、『携帯電話』の略としても使う。」という意味に最も近い語を選びなさい。","options":["生計","本文","山岳","携帯"],"answer":"携帯","explanationKo":"「携帯」의 핵심 의미는 휴대; 휴대전화이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3755","prompt":"「軍隊に所属し、軍事上の任務に従事する人。」という意味に最も近い語を選びなさい。","options":["創造","乗り換え","兵士","潜入"],"answer":"兵士","explanationKo":"「兵士」의 핵심 의미는 병사; 군인이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','grammar',1,'〜にもまして','{"pattern":"〜にもまして","meaningKo":"〜보다도 더","explanation":"〜にもまして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今年は例年にもまして、暑さが厳しい。","ko":"문맥에서 〜보다도 더의 의미로 쓰였다."},{"ja":"完成の喜びにもまして、支援への感謝を強く感じた。","ko":"이 문장도 〜보다도 더의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','grammar',2,'〜にもほどがある','{"pattern":"〜にもほどがある","meaningKo":"〜에도 정도가 있다","explanation":"〜にもほどがある는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"根拠のない批判にもほどがある。","ko":"문맥에서 〜에도 정도가 있다의 의미로 쓰였다."},{"ja":"連絡せずに一週間休むとは、無責任にもほどがある。","ko":"이 문장도 〜에도 정도가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今年は例年（　）、暑さが厳しい。","options":["〜が最後","〜に即して","〜ずにはおかない","〜にもまして"],"answer":"〜にもまして","explanationKo":"문맥상 〜보다도 더를 나타내는 「〜にもまして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠のない批判（　）。","options":["〜を皮切りに","〜ずにはすまない","〜にもほどがある","〜そばから"],"answer":"〜にもほどがある","explanationKo":"문맥상 〜에도 정도가 있다를 나타내는 「〜にもほどがある」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n重要な契約は専門家に確認する（　）。","options":["〜ないではすまない","〜に越したことはない","〜なり","〜を限りに"],"answer":"〜に越したことはない","explanationKo":"문맥상 〜보다 나은 것은 없다를 나타내는 「〜に越したことはない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-30','reading',1,'専門家の同意を結論にしない','{"passage":"複雑な問題について専門家の見解を集めることには、蓄積された知識を判断に反映できることという意義がある。一方、意見が一致しても同じ資料や前提に依存している場合があることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、合意の根拠と残る不確実性を分けて示すことが重要なのである。","questions":[{"prompt":"「専門家の同意を結論にしない」について筆者が最も重視していることは何か。","options":["合意の根拠と残る不確実性を分けて示すこと","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"合意の根拠と残る不確実性を分けて示すこと","explanationKo":"본문에서는 合意の根拠と残る不確実性を分けて示すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["意見が一致しても同じ資料や前提に依存している場合があること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"意見が一致しても同じ資料や前提に依存している場合があること","explanationKo":"주의할 점은 意見が一致しても同じ資料や前提に依存している場合があること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["蓄積された知識を判断に反映できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"蓄積された知識を判断に反映できること","explanationKo":"複雑な問題について専門家の見解を集めること에는 蓄積された知識を判断に反映できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3761","prompt":"「課題」の読み方として最も適切なものを選びなさい。","options":["きこん","かだい","たいかく","あかじ"],"answer":"かだい","explanationKo":"「課題」는 「かだい」라고 읽는다. 뜻은 과제; 해결해야 할 문제이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3762","prompt":"「退職」の読み方として最も適切なものを選びなさい。","options":["たいしょく","けいき","やしき","こうずい"],"answer":"たいしょく","explanationKo":"「退職」는 「たいしょく」라고 읽는다. 뜻은 퇴직이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3763","prompt":"「赤字」の読み方として最も適切なものを選びなさい。","options":["ふくごう","にんしき","ほうしゃ","あかじ"],"answer":"あかじ","explanationKo":"「赤字」는 「あかじ」라고 읽는다. 뜻은 적자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3764","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会場は過度な（　）を避け、落ち着いた雰囲気にまとめられていた。","options":["根気","真珠","装飾","結核"],"answer":"装飾","explanationKo":"문맥상 「装飾」가 가장 자연스럽다. 장식; 꾸밈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3765","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n経済的な理由で（　）を考える学生を支援する制度が設けられた。","options":["得点","退学","爆弾","教員"],"answer":"退学","explanationKo":"문맥상 「退学」가 가장 자연스럽다. 퇴학; 자퇴라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3766","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n乗客は非常口から無事に機内を（　）した。","options":["脱出","代用","指摘","中毒"],"answer":"脱出","explanationKo":"문맥상 「脱出」가 가장 자연스럽다. 탈출; 빠져나옴라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3767","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅から会場までは（　）で約十分かかる。","options":["本文","風習","高原","徒歩"],"answer":"徒歩","explanationKo":"문맥상 「徒歩」가 가장 자연스럽다. 도보; 걸어서 감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3768","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの部屋の面積はおよそ二十（　）メートルだ。","options":["当人","暴風","平方","天体"],"answer":"平方","explanationKo":"문맥상 「平方」가 가장 자연스럽다. 제곱; 평방라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3769","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n古い（　）沿いには江戸時代の町並みが一部残っている。","options":["補償","街道","幽霊","原形"],"answer":"街道","explanationKo":"문맥상 「街道」가 가장 자연스럽다. 가도; 주요 도로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3770","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工事による（　）が周辺の建物に影響していないか測定した。","options":["振動","少数","動力","天体"],"answer":"振動","explanationKo":"문맥상 「振動」가 가장 자연스럽다. 진동라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3771","prompt":"「身につける衣服。特に、舞台・映画・式典などで目的に合わせて着る服。」という意味に最も近い語を選びなさい。","options":["展示","類似","耕作","衣装"],"answer":"衣装","explanationKo":"「衣装」의 핵심 의미는 의상; 무대 의상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3772","prompt":"「相手を好ましく思う気持ち。また、親切にしようとする気持ち。」という意味に最も近い語を選びなさい。","options":["脱出","来場","好意","静止"],"answer":"好意","explanationKo":"「好意」의 핵심 의미는 호의; 좋은 감정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3773","prompt":"「死者の霊が、生前の姿などで現れるとされるもの。」という意味に最も近い語を選びなさい。","options":["素材","幽霊","配布","内臓"],"answer":"幽霊","explanationKo":"「幽霊」의 핵심 의미는 유령; 귀신이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3774","prompt":"「人の目、または世間の人が見る目。現代の日常語では『ひとめ』と読むことが多い。」という意味に最も近い語を選びなさい。","options":["人目","屋敷","洪水","家計"],"answer":"人目","explanationKo":"「人目」의 핵심 의미는 남의 눈; 세간의 시선이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3775","prompt":"「囲碁・将棋などで手を指した回数。また、目的を達するまでに必要な動作・手順の数。」という意味に最も近い語を選びなさい。","options":["立体","樹木","赤字","手数"],"answer":"手数","explanationKo":"「手数」의 핵심 의미는 수순 수; 손을 쓰는 횟수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','grammar',1,'〜に越したことはない','{"pattern":"〜に越したことはない","meaningKo":"〜보다 나은 것은 없다","explanation":"〜に越したことはない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"災害への備えは早いに越したことはない。","ko":"문맥에서 〜보다 나은 것은 없다의 의미로 쓰였다."},{"ja":"重要な契約は専門家に確認するに越したことはない。","ko":"이 문장도 〜보다 나은 것은 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','grammar',2,'〜としたところで','{"pattern":"〜としたところで","meaningKo":"설령 〜한다 해도","explanation":"〜としたところで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今から急いだとしたところで、開始時刻には間に合わない。","ko":"문맥에서 설령 〜한다 해도의 의미로 쓰였다."},{"ja":"全員が賛成したところで、予算がなければ実施できない。","ko":"이 문장도 설령 〜한다 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n災害への備えは早い（　）。","options":["〜を限りに","〜ないではすまない","〜に越したことはない","〜なり"],"answer":"〜に越したことはない","explanationKo":"문맥상 〜보다 나은 것은 없다를 나타내는 「〜に越したことはない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今から急いだ（　）、開始時刻には間に合わない。","options":["〜てやまない","〜としたところで","〜や否や","〜をものともせず"],"answer":"〜としたところで","explanationKo":"문맥상 설령 〜한다 해도를 나타내는 「〜としたところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n考え（　）、この失敗も貴重な経験になる。","options":["〜ようによっては","〜ようが〜まいが","〜をよそに","〜に足る"],"answer":"〜ようによっては","explanationKo":"문맥상 〜하는 방식에 따라서는를 나타내는 「〜ようによっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-31','reading',1,'地域の記憶を防災に生かす','{"passage":"過去の災害経験を聞き取り地図に残すことには、記録にない危険や避難の知恵を共有できることという意義がある。一方、記憶は時間とともに変化し個人差も大きいことには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、公的記録や地形情報と照合しながら複数の証言を扱うことが重要なのである。","questions":[{"prompt":"「地域の記憶を防災に生かす」について筆者が最も重視していることは何か。","options":["公的記録や地形情報と照合しながら複数の証言を扱うこと","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"公的記録や地形情報と照合しながら複数の証言を扱うこと","explanationKo":"본문에서는 公的記録や地形情報と照合しながら複数の証言を扱うこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["記憶は時間とともに変化し個人差も大きいこと","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"記憶は時間とともに変化し個人差も大きいこと","explanationKo":"주의할 점은 記憶は時間とともに変化し個人差も大きいこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["記録にない危険や避難の知恵を共有できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"記録にない危険や避難の知恵を共有できること","explanationKo":"過去の災害経験を聞き取り地図に残すこと에는 記録にない危険や避難の知恵を共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3781","prompt":"「返答」の読み方として最も適切なものを選びなさい。","options":["いっかつ","たいおう","へんとう","しゅにん"],"answer":"へんとう","explanationKo":"「返答」는 「へんとう」라고 읽는다. 뜻은 대답; 회답이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
