INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3787","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n授業で四季を題材にした（　）を一首作った。","options":["短歌","結成","転勤","振動"],"answer":"短歌","explanationKo":"문맥상 「短歌」가 가장 자연스럽다. 단가; 일본의 31음 정형시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3788","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n天候に恵まれ、今年の米は近年にない（　）となった。","options":["装飾","預金","色彩","豊作"],"answer":"豊作","explanationKo":"문맥상 「豊作」가 가장 자연스럽다. 풍작라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3789","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査では回答者を未婚・（　）などの属性別に集計した。","options":["兵器","最善","既婚","一帯"],"answer":"既婚","explanationKo":"문맥상 「既婚」가 가장 자연스럽다. 기혼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3790","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n早朝の便に間に合うよう、（　）の電車で空港へ向かった。","options":["原文","始発","意地","肥料"],"answer":"始発","explanationKo":"문맥상 「始発」가 가장 자연스럽다. 첫차; 첫 운행라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3791","prompt":"「施設の入口などで出入りを確認し、建物や敷地を警備する人。」という意味に最も近い語を選びなさい。","options":["守衛","原爆","本名","短歌"],"answer":"守衛","explanationKo":"「守衛」의 핵심 의미는 수위; 경비원이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3792","prompt":"「液体が沸点に達し、内部から盛んに気泡が生じて気体になること。」という意味に最も近い語を選びなさい。","options":["山脈","連中","上位","沸騰"],"answer":"沸騰","explanationKo":"「沸騰」의 핵심 의미는 비등; 끓음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3793","prompt":"「水を張って稲などを栽培する田。」という意味に最も近い語を選びなさい。","options":["支持","出生","水田","得点"],"answer":"水田","explanationKo":"「水田」의 핵심 의미는 논; 수전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3794","prompt":"「雨が降っている天候。」という意味に最も近い語を選びなさい。","options":["着陸","雨天","中毒","補充"],"answer":"雨天","explanationKo":"「雨天」의 핵심 의미는 우천; 비 오는 날씨이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3795","prompt":"「鉄鉱石などから鉄を取り出し、鉄鋼材料を製造すること。」という意味に最も近い語を選びなさい。","options":["製鉄","暴風","情熱","点検"],"answer":"製鉄","explanationKo":"「製鉄」의 핵심 의미는 제철; 철을 생산함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','grammar',1,'〜ようによっては','{"pattern":"〜ようによっては","meaningKo":"〜하는 방식에 따라서는","explanation":"〜ようによっては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"説明のしようによっては、誤解を招く恐れがある。","ko":"문맥에서 〜하는 방식에 따라서는의 의미로 쓰였다."},{"ja":"考えようによっては、この失敗も貴重な経験になる。","ko":"이 문장도 〜하는 방식에 따라서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','grammar',2,'〜が最後','{"pattern":"〜が最後","meaningKo":"일단 〜하면 끝장이다","explanation":"〜が最後는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"機密が一度流出したが最後、完全に回収するのは難しい。","ko":"문맥에서 일단 〜하면 끝장이다의 의미로 쓰였다."},{"ja":"彼は話し始めたが最後、なかなか止まらない。","ko":"이 문장도 일단 〜하면 끝장이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n説明のし（　）、誤解を招く恐れがある。","options":["〜に足る","〜ようによっては","〜ようが〜まいが","〜をよそに"],"answer":"〜ようによっては","explanationKo":"문맥상 〜하는 방식에 따라서는를 나타내는 「〜ようによっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n機密が一度流出した（　）、完全に回収するのは難しい。","options":["〜が最後","〜と相まって","〜にかたくない","〜たりとも"],"answer":"〜が最後","explanationKo":"문맥상 일단 〜하면 끝장이다를 나타내는 「〜が最後」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n片付ける（　）、子どもが玩具を広げていく。","options":["〜に即して","〜べからず","〜であれ","〜そばから"],"answer":"〜そばから","explanationKo":"문맥상 〜하자마자 곧를 나타내는 「〜そばから」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-01','reading',1,'退職後も知識を残す','{"passage":"経験のある職員から業務知識を引き継ぐことには、担当者が変わっても組織の機能を保てることという意義がある。一方、文書化だけでは状況に応じた判断の理由が伝わらないことには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、実例を使った共同作業と振り返りを引継ぎに含めることが重要なのである。","questions":[{"prompt":"「退職後も知識を残す」について筆者が最も重視していることは何か。","options":["実例を使った共同作業と振り返りを引継ぎに含めること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"実例を使った共同作業と振り返りを引継ぎに含めること","explanationKo":"본문에서는 実例を使った共同作業と振り返りを引継ぎに含めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["文書化だけでは状況に応じた判断の理由が伝わらないこと","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"文書化だけでは状況に応じた判断の理由が伝わらないこと","explanationKo":"주의할 점은 文書化だけでは状況に応じた判断の理由が伝わらないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当者が変わっても組織の機能を保てること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"担当者が変わっても組織の機能を保てること","explanationKo":"経験のある職員から業務知識を引き継ぐこと에는 担当者が変わっても組織の機能を保てること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3801","prompt":"「案の定」の読み方として最も適切なものを選びなさい。","options":["じんそく","おおはば","けんぜん","あんのじょう"],"answer":"あんのじょう","explanationKo":"「案の定」는 「あんのじょう」라고 읽는다. 뜻은 아니나 다를까; 예상대로이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3802","prompt":"「主任」の読み方として最も適切なものを選びなさい。","options":["どうじょう","せいいく","しゅにん","ふっかつ"],"answer":"しゅにん","explanationKo":"「主任」는 「しゅにん」라고 읽는다. 뜻은 주임; 담당 책임자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3803","prompt":"「情熱」の読み方として最も適切なものを選びなさい。","options":["でんごん","じょうねつ","かごう","たいがく"],"answer":"じょうねつ","explanationKo":"「情熱」는 「じょうねつ」라고 읽는다. 뜻은 열정; 정열이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3804","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n少人数教育を維持するには、十分な数の（　）を確保する必要がある。","options":["教員","当選","用品","死刑"],"answer":"教員","explanationKo":"문맥상 「教員」가 가장 자연스럽다. 교원; 교사라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3805","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査隊は未踏の洞窟を（　）し、これまで知られていなかった生物を発見した。","options":["監視","充実","化合","探検"],"answer":"探検","explanationKo":"문맥상 「探検」가 가장 자연스럽다. 탐험; 미지의 곳을 조사함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3806","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n留学時代の友人と十年ぶりに（　）し、昔の思い出を語り合った。","options":["収集","配布","再会","同居"],"answer":"再会","explanationKo":"문맥상 「再会」가 가장 자연스럽다. 재회; 다시 만남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3807","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新人候補が予想を上回る支持を集め、初めての選挙で（　）した。","options":["屋敷","当選","新築","契機"],"answer":"当選","explanationKo":"문맥상 「当選」가 가장 자연스럽다. 당선; 당첨라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3808","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会議資料は紙では（　）せず、事前に共有フォルダへ保存することになった。","options":["配布","映像","旅客","交互"],"answer":"配布","explanationKo":"문맥상 「配布」가 가장 자연스럽다. 배포; 나누어 줌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3809","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n近年は異常（　）による豪雨や猛暑が各地で頻繁に報告されている。","options":["対応","直面","募金","気象"],"answer":"気象","explanationKo":"문맥상 「気象」가 가장 자연스럽다. 기상; 대기 현상라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3810","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n急な出費に備えて、毎月一定額を普通（　）に回している。","options":["爆弾","教員","預金","学歴"],"answer":"預金","explanationKo":"문맥상 「預金」가 가장 자연스럽다. 예금; 은행에 맡긴 돈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3811","prompt":"「その場にいない相手へ、別の人を通じて言葉・用件を伝えること。また、その内容。」という意味に最も近い語を選びなさい。","options":["指摘","伝言","欲望","代用"],"answer":"伝言","explanationKo":"「伝言」의 핵심 의미는 전언; 전달 메시지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3812","prompt":"「一週間おき。二週間に一度の間隔。」という意味に最も近い語を選びなさい。","options":["隔週","真実","良好","大幅"],"answer":"隔週","explanationKo":"「隔週」의 핵심 의미는 격주; 한 주 걸러이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3813","prompt":"「ある物の垂直方向のすぐ下。」という意味に最も近い語を選びなさい。","options":["動力","天体","当人","真下"],"answer":"真下","explanationKo":"「真下」의 핵심 의미는 바로 아래; 정하방이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3814","prompt":"「相手の機嫌を取るために言う、実意のない褒め言葉。」という意味に最も近い語を選びなさい。","options":["好意","安静","世辞","残高"],"answer":"世辞","explanationKo":"「世辞」의 핵심 의미는 아첨; 빈말; 인사치레이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3815","prompt":"「空気の流れ。」という意味に最も近い語を選びなさい。","options":["出動","気流","守衛","姓名"],"answer":"気流","explanationKo":"「気流」의 핵심 의미는 기류; 공기의 흐름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','grammar',1,'〜そばから','{"pattern":"〜そばから","meaningKo":"〜하자마자 곧","explanation":"〜そばから는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"新しい用語を覚えるそばから、忘れてしまう。","ko":"문맥에서 〜하자마자 곧의 의미로 쓰였다."},{"ja":"片付けるそばから、子どもが玩具を広げていく。","ko":"이 문장도 〜하자마자 곧의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','grammar',2,'〜なり','{"pattern":"〜なり","meaningKo":"〜하자마자","explanation":"〜なり는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は部屋に入るなり、結果を尋ねた。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"知らせを聞くなり、彼女は現場へ向かった。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n新しい用語を覚える（　）、忘れてしまう。","options":["〜そばから","〜に即して","〜べからず","〜であれ"],"answer":"〜そばから","explanationKo":"문맥상 〜하자마자 곧를 나타내는 「〜そばから」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は部屋に入る（　）、結果を尋ねた。","options":["〜を皮切りに","〜まじき","〜といえども","〜なり"],"answer":"〜なり","explanationKo":"문맥상 〜하자마자를 나타내는 「〜なり」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n合図が出る（　）、選手たちは走り出した。","options":["〜ずにはおかない","〜ながらに","〜や否や","〜を限りに"],"answer":"〜や否や","explanationKo":"문맥상 〜하자마자를 나타내는 「〜や否や」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-02','reading',1,'議事録で沈黙を同意にしない','{"passage":"会議の決定と発言を記録することには、後から判断の経緯と責任を確認できることという意義がある。一方、発言しなかった人を賛成と扱うと懸念や保留が消えることには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、決定前に参加者ごとの異議と保留を確認することが重要なのである。","questions":[{"prompt":"「議事録で沈黙を同意にしない」について筆者が最も重視していることは何か。","options":["決定前に参加者ごとの異議と保留を確認すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"決定前に参加者ごとの異議と保留を確認すること","explanationKo":"본문에서는 決定前に参加者ごとの異議と保留を確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["発言しなかった人を賛成と扱うと懸念や保留が消えること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"発言しなかった人を賛成と扱うと懸念や保留が消えること","explanationKo":"주의할 점은 発言しなかった人を賛成と扱うと懸念や保留が消えること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["後から判断の経緯と責任を確認できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"後から判断の経緯と責任を確認できること","explanationKo":"会議の決定と発言を記録すること에는 後から判断の経緯と責任を確認できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3821","prompt":"「版画」の読み方として最も適切なものを選びなさい。","options":["はんが","りょかく","りったい","じゅもく"],"answer":"はんが","explanationKo":"「版画」는 「はんが」라고 읽는다. 뜻은 판화이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3822","prompt":"「字体」の読み方として最も適切なものを選びなさい。","options":["つなみ","へいし","ぶつぞう","じたい"],"answer":"じたい","explanationKo":"「字体」는 「じたい」라고 읽는다. 뜻은 자체; 글자 모양; 서체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3823","prompt":"「姓名」の読み方として最も適切なものを選びなさい。","options":["きしょう","こうどく","せいめい","しんし"],"answer":"せいめい","explanationKo":"「姓名」는 「せいめい」라고 읽는다. 뜻은 성명; 성과 이름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3824","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n暖かくなると種が（　）し始める。","options":["津波","発芽","脚本","陶器"],"answer":"発芽","explanationKo":"문맥상 「発芽」가 가장 자연스럽다. 발아; 싹틈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3825","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼女は大学で（　）を専攻し、古代の遺跡を研究している。","options":["考古学","処置","推理","携帯"],"answer":"考古学","explanationKo":"문맥상 「考古学」가 가장 자연스럽다. 고고학라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3826","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n転勤後は会社の（　）に住むことになった。","options":["着席","夜行","著書","社宅"],"answer":"社宅","explanationKo":"문맥상 「社宅」가 가장 자연스럽다. 사택; 회사 제공 주택라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3827","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n留学の準備に集中するため、一年間（　）した。","options":["飼育","看護","休学","社宅"],"answer":"休学","explanationKo":"문맥상 「休学」가 가장 자연스럽다. 휴학라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3828","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n公共機関には、正確な情報を迅速に提供する役割を（　）責任がある。","options":["控える","果たす","逃げ出す","導く"],"answer":"果たす","explanationKo":"문맥상 「果たす」가 가장 자연스럽다. 완수하다; 다하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3829","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の意見を聞くため、定期的な意見交換の場を（　）ことになった。","options":["設ける","定まる","催す","仕掛ける"],"answer":"設ける","explanationKo":"문맥상 「設ける」가 가장 자연스럽다. 마련하다; 설치하다; 제정하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3830","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度上の責任から（　）ために名義だけを変えることは認められない。","options":["設ける","誤る","取り除く","逃れる"],"answer":"逃れる","explanationKo":"문맥상 「逃れる」가 가장 자연스럽다. 벗어나다; 피하다; 면하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3831","prompt":"「人・意見・事実・文化などを拒まず認め、自分の側に取り入れる。」という意味に最も近い語を選びなさい。","options":["控える","栄える","受け入れる","導く"],"answer":"受け入れる","explanationKo":"「受け入れる」의 핵심 의미는 받아들이다; 수용하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3832","prompt":"「容器・場所などをいっぱいにする。また、条件・基準・要求などを十分に満足させる。」という意味に最も近い語を選びなさい。","options":["定める","満たす","滅びる","受け入れる"],"answer":"満たす","explanationKo":"「満たす」의 핵심 의미는 채우다; 충족하다; 만족시키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3833","prompt":"「判断・方法・理解などを間違える。」という意味に最も近い語を選びなさい。","options":["誤る","果たす","歩む","仕上げる"],"answer":"誤る","explanationKo":"「誤る」의 핵심 의미는 잘못하다; 그르치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3834","prompt":"「柔らかいものを硬くする。また、方針・決意・基盤・体制などを確かなものにする。」という意味に最も近い語を選びなさい。","options":["逃げ出す","導く","控える","固める"],"answer":"固める","explanationKo":"「固める」의 핵심 의미는 굳히다; 다지다; 확정하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3835","prompt":"「目的のために装置・罠などを設ける。また、相手に働きかけたり、ある行為を始めたりする。」という意味に最も近い語を選びなさい。","options":["明かす","定まる","仕掛ける","逃れる"],"answer":"仕掛ける","explanationKo":"「仕掛ける」의 핵심 의미는 장치를 설치하다; 일을 걸다; 시작하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','grammar',1,'〜や否や','{"pattern":"〜や否や","meaningKo":"〜하자마자","explanation":"〜や否や는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"開場するや否や、観客が一斉に席へ向かった。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"合図が出るや否や、選手たちは走り出した。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','grammar',2,'〜ようが〜まいが','{"pattern":"〜ようが〜まいが","meaningKo":"〜하든 말든","explanation":"〜ようが〜まいが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"周囲が反対しようがしまいが、必要な改革は進める。","ko":"문맥에서 〜하든 말든의 의미로 쓰였다."},{"ja":"雨が降ろうが降るまいが、調査は予定どおり行う。","ko":"이 문장도 〜하든 말든의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n開場する（　）、観客が一斉に席へ向かった。","options":["〜を限りに","〜ずにはおかない","〜ながらに","〜や否や"],"answer":"〜や否や","explanationKo":"문맥상 〜하자마자를 나타내는 「〜や否や」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n周囲が（　）、必要な改革は進める。","options":["〜ずにはすまない","〜にもまして","〜ようが〜まいが","〜をものともせず"],"answer":"〜ようが〜まいが","explanationKo":"문맥상 〜하든 말든를 나타내는 「〜ようが〜まいが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n強い風が乾燥（　）、火災の被害を広げた。","options":["〜にもほどがある","〜と相まって","〜をよそに","〜ないではすまない"],"answer":"〜と相まって","explanationKo":"문맥상 〜와 어우러져; 〜와 맞물려를 나타내는 「〜と相まって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-03','reading',1,'改善の効果を比較可能にする','{"passage":"制度を変更して結果が良くなったか調べることには、有効な方法を残し問題のある方法を修正できることという意義がある。一方、変更前後で対象や測定方法が違えば差を効果と誤認することには注意が必要だ。見かけ上の成果だけで結論を出さず、誰にどのような影響が生じるかを継続して確かめなければならない。したがって、同じ条件で比較できない要因を明示して解釈することが重要なのである。","questions":[{"prompt":"「改善の効果を比較可能にする」について筆者が最も重視していることは何か。","options":["同じ条件で比較できない要因を明示して解釈すること","短期の成果だけで方法を固定すること","影響を受ける対象を限定しないこと","異なる条件をすべて同じものとして扱うこと"],"answer":"同じ条件で比較できない要因を明示して解釈すること","explanationKo":"본문에서는 同じ条件で比較できない要因を明示して解釈すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["変更前後で対象や測定方法が違えば差を効果と誤認すること","目的を示すと判断が遅れること","結果を確認すると利点が失われること","複数の立場を含めると記録できなくなること"],"answer":"変更前後で対象や測定方法が違えば差を効果と誤認すること","explanationKo":"주의할 점은 変更前後で対象や測定方法が違えば差を効果と誤認すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["有効な方法を残し問題のある方法を修正できること","見かけ上の成果だけで結論を出すべきだ","実施後の影響を確かめる必要はない","対象による違いは考慮しなくてよい"],"answer":"有効な方法を残し問題のある方法を修正できること","explanationKo":"制度を変更して結果が良くなったか調べること에는 有効な方法を残し問題のある方法を修正できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
